// DOPA MODE for Claude Code. DOPA is short for dopamine.
//
// Above the prompt: HP (context left), STAMINA (plan limit left), cost and files edited,
// with warnings before they bite. Everything you do and every real milestone goes up as fireworks
// in a sky above the prompt: a finished turn and the files it edited, commits, pushes, pull requests,
// tests passing and CI going green. It also keeps trophies, a daily command card, a focus timer and
// a session recap.
//
// It reads and never rewrites: no prompt, tool result or transcript row is changed.
// The only process it can start is `gh pr checks`, and only when you type /dopa boss.

import { atom, read, update } from 'claude-code'
import type { Elements, EngineInterface, Register, RenderElement, Timer } from 'claude-code'
import type { BossState, FocusState, Limit, Meter, Moment, Profile, SessionStats, Settings, TestState, TurnInfo } from '../types'

type Api = EngineInterface
type BoxText = Pick<Elements['terminal'], 'Box' | 'Text'>

// ---------------------------------------------------------------- constants

const FRAME_MS = 40

// The hold-lamp ladder from pachinko: white, blue, green, red, gold, and rainbow, which means confirmed.
// One ladder drives the hit count, the reveal lamp and the runner's trail; rainbow is kept for the rarest.
const LADDER = ['#e9e6f2', '#3d8bff', '#2ed47a', '#ff4545', '#ffc928'] as const
const RAINBOW = ['#ff4545', '#ff9a1f', '#ffe14d', '#2ed47a', '#2fc6ff', '#5b6bff', '#c45bff']
const PINK = '#ff4545'
const GOLD = '#ffc928'
const ORANGE = '#ff9a1f'

const COMBO_TIERS = [
  { at: 50, word: 'RAINBOW', level: 5 },
  { at: 30, word: 'FEVER', level: 4 },
  { at: 20, word: 'EXCELLENT', level: 3 },
  { at: 10, word: 'GREAT', level: 2 },
  { at: 5, word: 'GOOD', level: 1 },
  { at: 0, word: '', level: 0 },
] as const

/** Test runners whose summaries the slot reads. It reads what Claude already ran; it never runs tests. */
const TEST_COMMAND =
  /\b(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?test\b|\bnpx\s+(?:jest|vitest|mocha)\b|^\s*(?:jest|vitest|mocha)\b|\bpytest\b|\bpython3?\s+-m\s+(?:pytest|unittest)\b|\bgo\s+test\b|\bcargo\s+(?:test|nextest)\b|\b(?:mvn|mvnw)\b[^|;&]*\b(?:test|verify)\b|\b(?:gradle|gradlew)\b[^|;&]*\b(?:test|check|build)\b|\brspec\b|\bphpunit\b|\bdotnet\s+test\b|\bdeno\s+test\b|\bclaude\s+plugin\s+test\b/
const CHECKS_COMMAND = /\bgh\s+pr\s+checks\b/

const TROPHIES = [
  { id: 'first-clear', name: 'First clear', hint: 'finish a turn' },
  { id: 'commit', name: 'Committed', hint: 'see Claude make a commit' },
  { id: 'merged', name: 'Merged', hint: 'see a pull request merged' },
  { id: 'hit-10', name: 'Ten-hit turn', hint: 'reach 10 HIT in one turn' },
  { id: 'hit-30', name: 'Fever turn', hint: 'reach 30 HIT in one turn' },
  { id: 'hit-50', name: 'Rainbow turn', hint: 'reach 50 HIT in one turn' },
  { id: 'streak-10', name: 'Ten in a row', hint: 'finish 10 turns without an interrupt' },
  { id: 'all-green', name: 'All green', hint: 'see a test run pass' },
  { id: 'comeback', name: 'Comeback', hint: 'turn a red test run green' },
  { id: 'boss', name: 'Boss down', hint: 'see every pull request check pass' },
  { id: 'self-compact', name: 'Self care', hint: 'compact before auto-compact does it for you' },
  { id: 'dex-10', name: 'Collector', hint: 'capture 10 commands' },
  { id: 'focus-1', name: 'Deep work', hint: 'finish a focus session' },
  { id: 'focus-4', name: 'Full cycle', hint: 'finish 4 focus sessions in one day' },
  { id: 'dan', name: '1 DAN', hint: 'reach LV 11' },
] as const
type TrophyId = (typeof TROPHIES)[number]['id']

export const FRESH_PROFILE: Profile = {
  level: 1,
  xp: 0,
  totalXp: 0,
  clears: 0,
  streak: 0,
  bestStreak: 0,
  bestCombo: 0,
  moments: { commit: 0, push: 0, pr: 0, merge: 0 },
}
export const DEFAULT_SETTINGS: Settings = { isOn: true, sfx: true, spinner: true, meters: true, alerts: true, typing: true, fireworks: true }
const IDLE_TURN: TurnInfo = { isWorking: false, combo: 0, startedAt: 0, word: 'Cooking', move: '' }
export const FRESH_STATS: SessionStats = {
  startedAt: 0,
  turns: 0,
  toolCalls: 0,
  tools: {},
  files: {},
  inputTokens: 0,
  cacheReadTokens: 0,
  outputTokens: 0,
  workMs: 0,
  bestCombo: 0,
  moments: { commit: 0, push: 0, pr: 0, merge: 0 },
}

// Held by the host, so they survive a hot reload of this file.
const profileAtom = atom({ plugin: 'dopa-mode', key: 'profile' } as const, FRESH_PROFILE)
const settingsAtom = atom({ plugin: 'dopa-mode', key: 'settings' } as const, DEFAULT_SETTINGS)
const turnAtom = atom({ plugin: 'dopa-mode', key: 'turn' } as const, IDLE_TURN)
const meterAtom = atom({ plugin: 'dopa-mode', key: 'meter' } as const, null)
const statsAtom = atom({ plugin: 'dopa-mode', key: 'stats' } as const, FRESH_STATS)
const testsAtom = atom({ plugin: 'dopa-mode', key: 'tests' } as const, { last: null, greenStreak: 0, wasRed: false })
const bossAtom = atom({ plugin: 'dopa-mode', key: 'boss' } as const, null)
const focusAtom = atom({ plugin: 'dopa-mode', key: 'focus' } as const, null)

// ---------------------------------------------------------------- game rules

export function xpToNext(level: number): number {
  return 80 + level * 40
}

/** Ranks as in shogi, go and arcade dan exams: 10 KYU up to 1 KYU, 1 DAN up to 9 DAN, then MEIJIN. */
export function levelTitle(level: number): string {
  if (level <= 10) return `${11 - Math.max(1, level)} KYU`
  if (level <= 19) return `${level - 10} DAN`
  return 'MEIJIN'
}

/** XP for a finished turn: its hits, the files it edited and how long it ran, a little more on a streak. */
export function turnXp(combo: number, files: number, durationMs: number, streak: number): number {
  const base = 10 + 4 * Math.min(combo, 60) + 12 * Math.min(files, 20) + Math.min(60, Math.floor(durationMs / 2000))
  return Math.round(base * (1 + Math.min(streak, 10) * 0.05))
}

/** A finished turn on the profile: XP lands, levels roll over, the streak grows. */
export function finishTurn(before: Profile, xp: number, combo: number): Profile {
  const p = grantXp(before, xp)
  return { ...p, clears: p.clears + 1, streak: p.streak + 1, bestStreak: Math.max(p.bestStreak, p.streak + 1), bestCombo: Math.max(p.bestCombo, combo) }
}

export function normalizeProfile(raw: unknown): Profile {
  const p = (raw !== null && typeof raw === 'object' ? raw : {}) as Partial<Profile> & { pulls?: unknown }
  const num = (v: unknown, d: number) => (typeof v === 'number' && Number.isFinite(v) ? v : d)
  const m = (p.moments ?? {}) as Partial<Record<Moment, number>>
  return {
    level: Math.max(1, Math.floor(num(p.level, 1))),
    xp: Math.max(0, num(p.xp, 0)),
    totalXp: Math.max(0, num(p.totalXp, 0)),
    clears: Math.max(0, num(p.clears, num(p.pulls, 0))), // older saves counted finished turns as pulls
    streak: Math.max(0, num(p.streak, 0)),
    bestStreak: Math.max(0, num(p.bestStreak, 0)),
    bestCombo: Math.max(0, num(p.bestCombo, 0)),
    moments: { commit: Math.max(0, num(m.commit, 0)), push: Math.max(0, num(m.push, 0)), pr: Math.max(0, num(m.pr, 0)), merge: Math.max(0, num(m.merge, 0)) },
  }
}

export function normalizeSettings(raw: unknown): Settings {
  const s = (raw !== null && typeof raw === 'object' ? raw : {}) as Partial<Settings>
  const flag = (v: unknown, d: boolean) => (typeof v === 'boolean' ? v : d)
  return {
    isOn: flag(s.isOn, DEFAULT_SETTINGS.isOn),
    sfx: flag(s.sfx, DEFAULT_SETTINGS.sfx),
    spinner: flag(s.spinner, DEFAULT_SETTINGS.spinner),
    meters: flag(s.meters, DEFAULT_SETTINGS.meters),
    alerts: flag(s.alerts, DEFAULT_SETTINGS.alerts),
    typing: flag(s.typing, DEFAULT_SETTINGS.typing),
    fireworks: flag(s.fireworks, DEFAULT_SETTINGS.fireworks),
  }
}

/** What a tool call is doing, in a few words: EDIT signup.ts, BASH npm test, GREP validate. */
export function moveLabel(e: unknown): string {
  const a = e as Record<string, unknown>
  const tool = typeof a.tool === 'string' ? a.tool : ''
  const str = (v: unknown) => (typeof v === 'string' ? v : '')
  const base = (v: unknown) => str(v).split(/[\\/]/).pop() ?? ''
  const clip = (text: string) => (text.length > 28 ? `${text.slice(0, 27)}…` : text)
  const host = (v: unknown) => {
    try {
      return new URL(str(v)).hostname
    } catch {
      return ''
    }
  }
  const verbs: Record<string, [string, string]> = {
    Edit: ['EDIT', base(a.file_path)],
    MultiEdit: ['EDIT', base(a.file_path)],
    NotebookEdit: ['EDIT', base(a.notebook_path)],
    Write: ['WRITE', base(a.file_path)],
    Read: ['READ', base(a.file_path)],
    Bash: ['BASH', str(a.command).trim().split(/\r?\n/)[0] ?? ''],
    PowerShell: ['PS', str(a.command).trim().split(/\r?\n/)[0] ?? ''],
    Grep: ['GREP', str(a.pattern)],
    Glob: ['GLOB', str(a.pattern)],
    WebFetch: ['WEB', host(a.url)],
    WebSearch: ['SEARCH', str(a.query)],
    Task: ['AGENT', str(a.description)],
    Agent: ['AGENT', str(a.description)],
    TodoWrite: ['TODO', ''],
    AskUserQuestion: ['ASK', ''],
  }
  const known = verbs[tool]
  if (known) return `${known[0]} ${clip(known[1])}`.trim()
  if (tool.startsWith('mcp__')) return `MCP ${tool.split('__')[1] ?? ''}`.trim()
  return tool.toUpperCase().slice(0, 16)
}

export function comboTier(combo: number) {
  return COMBO_TIERS.find((t) => combo >= t.at) ?? COMBO_TIERS[COMBO_TIERS.length - 1]!
}

/** A ladder step's color; the rainbow step cycles. */
function ladderColor(level: number, phase: number): string {
  return level >= 5 ? RAINBOW[phase % RAINBOW.length]! : LADDER[Math.max(0, level)]!
}

export type TestCount = { passed: number; failed: number; isKnown: boolean }

/** Reads the summary of common test runners. Null when the output has no summary it knows. */
export function parseTestOutput(text: string): TestCount | null {
  const last = (re: RegExp): RegExpMatchArray | null => {
    let found: RegExpMatchArray | null = null
    for (const m of text.matchAll(re)) found = m
    return found
  }
  const n = (v: string | undefined) => (v ? Number(v) : 0)
  const counts = (line: string, passWord = 'passed') => ({
    passed: n(line.match(new RegExp(`(\\d+) ${passWord}`))?.[1]),
    failed: n(line.match(/(\d+) failed/)?.[1]),
    isKnown: true,
  })
  let m = last(/Tests:[ \t]+[^\n]*?\d+ total/g) // Jest
  if (m) return counts(m[0])
  m = last(/^\s*Tests\s+[^\n]*?\(\d+\)/gm) // Vitest
  if (m) return counts(m[0])
  m = last(/Tests run: (\d+), Failures: (\d+), Errors: (\d+), Skipped: (\d+)/g) // Maven Surefire
  if (m) {
    const failed = n(m[2]) + n(m[3])
    return { passed: n(m[1]) - failed - n(m[4]), failed, isKnown: true }
  }
  m = last(/(\d+) tests? completed, (\d+) failed/g) // Gradle
  if (m) return { passed: n(m[1]) - n(m[2]), failed: n(m[2]), isKnown: true }
  m = last(/((?:\d+ (?:passed|failed|errors?|skipped|xfailed|xpassed|warnings?|deselected),? ?)+) in [\d.]+s/g) // pytest
  if (m) {
    const line = m[1] ?? ''
    return { passed: n(line.match(/(\d+) passed/)?.[1]), failed: n(line.match(/(\d+) failed/)?.[1]) + n(line.match(/(\d+) errors?/)?.[1]), isKnown: true }
  }
  const cargo = [...text.matchAll(/test result: \w+\. (\d+) passed; (\d+) failed/g)] // cargo, one line per crate
  if (cargo.length > 0) return { passed: cargo.reduce((sum, c) => sum + n(c[1]), 0), failed: cargo.reduce((sum, c) => sum + n(c[2]), 0), isKnown: true }
  m = last(/(\d+) examples?, (\d+) failures?/g) // RSpec
  if (m) return { passed: n(m[1]) - n(m[2]), failed: n(m[2]), isKnown: true }
  m = last(/Failed:\s+(\d+), Passed:\s+(\d+)/g) // dotnet test
  if (m) return { passed: n(m[2]), failed: n(m[1]), isKnown: true }
  m = last(/OK \((\d+) tests?/g) // PHPUnit, green
  if (m) return { passed: n(m[1]), failed: 0, isKnown: true }
  m = last(/Tests: (\d+), Assertions: \d+(?:, Errors: (\d+))?(?:, Failures: (\d+))?/g) // PHPUnit, red
  if (m) {
    const failed = n(m[2]) + n(m[3])
    return { passed: n(m[1]) - failed, failed, isKnown: true }
  }
  const passing = last(/(\d+) passing/g) // Mocha
  if (passing) return { passed: n(passing[1]), failed: n(last(/(\d+) failing/g)?.[1]), isKnown: true }
  m = last(/(?:ok|FAILED) \| (\d+) passed[^|\n]*\| (\d+) failed/g) // Deno
  if (m) return { passed: n(m[1]), failed: n(m[2]), isKnown: true }
  const bun = last(/^\s*(\d+) pass$/gm) // bun test, claude plugin test
  if (bun) return { passed: n(bun[1]), failed: n(last(/^\s*(\d+) fail$/gm)?.[1]), isKnown: true }
  m = last(/Ran (\d+) tests? in/g) // unittest
  if (m) {
    const f = last(/FAILED \(([^)]*)\)/g)?.[1] ?? ''
    const failed = n(f.match(/failures=(\d+)/)?.[1]) + n(f.match(/errors=(\d+)/)?.[1])
    return { passed: n(m[1]) - failed, failed, isKnown: true }
  }
  const goFail = (text.match(/^--- FAIL:/gm) ?? []).length + (text.match(/^FAIL\t/gm) ?? []).length // go test
  const goPass = (text.match(/^ok\s+\S+/gm) ?? []).length + (text.match(/^--- PASS:/gm) ?? []).length
  if (goFail + goPass > 0) return { passed: goPass, failed: goFail, isKnown: false }
  if (/BUILD SUCCESSFUL/.test(text)) return { passed: 0, failed: 0, isKnown: false }
  if (/BUILD FAILED/.test(text)) return { passed: 0, failed: 1, isKnown: false }
  return null
}

export type CheckCount = { total: number; passed: number; failed: number; pending: number }

/** Reads `gh pr checks` output: its JSON (`--json name,bucket`) or its plain tab-separated table. */
export function parseChecks(text: string): CheckCount | null {
  const tally = (buckets: string[]): CheckCount | null => {
    if (buckets.length === 0) return null
    const c = { total: buckets.length, passed: 0, failed: 0, pending: 0 }
    for (const b of buckets) {
      if (b === 'pass' || b === 'skipping') c.passed += 1
      else if (b === 'fail' || b === 'cancel') c.failed += 1
      else c.pending += 1
    }
    return c
  }
  const trimmed = text.trim()
  if (trimmed.startsWith('[')) {
    try {
      const rows = JSON.parse(trimmed) as Array<{ bucket?: unknown }>
      return tally(rows.map((row) => String(row.bucket ?? '').toLowerCase()))
    } catch {
      // Not JSON after all: try the table.
    }
  }
  const buckets = trimmed
    .split('\n')
    .map((line) => (line.split('\t')[1] ?? '').trim().toLowerCase())
    .filter((b) => ['pass', 'fail', 'pending', 'skipping', 'cancel'].includes(b))
  return tally(buckets)
}

type Dex = { captured: string[]; day: string; card: string | null; isCardCaptured: boolean }

export function normalizeDex(raw: unknown): Dex {
  const d = (raw !== null && typeof raw === 'object' ? raw : {}) as Partial<Dex>
  return {
    captured: Array.isArray(d.captured) ? d.captured.filter((x): x is string => typeof x === 'string') : [],
    day: typeof d.day === 'string' ? d.day : '',
    card: typeof d.card === 'string' ? d.card : null,
    isCardCaptured: d.isCardCaptured === true,
  }
}


export function grantXp(p: Profile, xp: number): Profile {
  const q: Profile = { ...p, xp: p.xp + xp, totalXp: p.totalXp + xp }
  while (q.xp >= xpToNext(q.level)) {
    q.xp -= xpToNext(q.level)
    q.level += 1
  }
  return q
}

function localDay(now = new Date()): string {
  const pad = (x: number) => String(x).padStart(2, '0')
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`
}

function clampMinutes(arg: string, fallback: number): number {
  const v = Number(arg)
  return Number.isFinite(v) && v > 0 ? Math.min(180, Math.max(1, Math.round(v))) : fallback
}

export function fmt(n: number): string {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, '0')}s`
  return `${Math.floor(s / 3600)}h ${String(Math.floor((s % 3600) / 60)).padStart(2, '0')}m`
}

/** 1234 to 1.2k, 1234567 to 1.2M. */
export function short(n: number): string {
  if (n >= 1_000_000) return `${+(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${+(n / 1_000).toFixed(1)}k`
  return String(Math.round(n))
}

/** Time until an ISO timestamp: 47m, 2h 05m, 3d 4h. Empty when unknown. */
export function untilText(iso: string | undefined, now = Date.now()): string {
  if (!iso) return ''
  const ms = Date.parse(iso) - now
  if (!Number.isFinite(ms)) return ''
  if (ms <= 0) return 'now'
  const minutes = Math.ceil(ms / 60_000)
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ${String(minutes % 60).padStart(2, '0')}m`
  return `${Math.floor(hours / 24)}d ${hours % 24}h`
}

export function limitName(kind: string, isShort = false): string {
  if (kind === 'five_hour') return isShort ? '5h' : '5-hour'
  if (kind === 'seven_day') return isShort ? '7d' : 'weekly'
  if (kind.startsWith('seven_day_')) return `${isShort ? '7d' : 'weekly'} ${kind.slice(10)}`
  if (kind === 'spend_limit') return 'spend'
  return kind.replace(/_/g, ' ')
}

type UsageLike = {
  context: { tokens?: number; window: number; percent?: number }
  rateLimits: readonly Limit[]
  cost?: { usd: number }
}

export function toMeter(u: UsageLike): Meter {
  const { tokens, window, percent } = u.context
  const ctxPercent = percent ?? (tokens !== undefined && window > 0 ? Math.round((tokens / window) * 100) : null)
  return {
    ctxPercent,
    ctxTokens: tokens ?? null,
    ctxWindow: window,
    limits: u.rateLimits.map((l) =>
      l.resetsAt
        ? { kind: l.kind, percentUsed: l.percentUsed, resetsAt: l.resetsAt }
        : { kind: l.kind, percentUsed: l.percentUsed },
    ),
    usd: u.cost?.usd ?? null,
  }
}

const EDIT_TOOLS = new Set(['Edit', 'MultiEdit', 'Write', 'NotebookEdit'])
// Claude Code on Windows runs commands through PowerShell, which answers in the same shape as Bash.
const SHELL_TOOLS = new Set(['Bash', 'PowerShell'])

/** The file an edit tool call changes, relative to the session's directory. */
export function editedFile(e: unknown, root: string): string | null {
  const args = e as { tool?: string; file_path?: unknown; notebook_path?: unknown }
  if (!args.tool || !EDIT_TOOLS.has(args.tool)) return null
  const path =
    typeof args.file_path === 'string' ? args.file_path : typeof args.notebook_path === 'string' ? args.notebook_path : null
  if (!path) return null
  for (const sep of ['/', '\\']) {
    const base = root.endsWith(sep) ? root : root + sep
    if (root && path.startsWith(base)) return path.slice(base.length)
  }
  return path
}

function random01(): number {
  const a = new Uint32Array(1)
  crypto.getRandomValues(a)
  return (a[0] ?? 0) / 4294967296
}

function pick<T>(list: readonly T[]): T {
  return list[Math.floor(random01() * list.length)] ?? (list[0] as T)
}

// ---------------------------------------------------------------- live state

let settings: Settings = DEFAULT_SETTINGS
let live: TurnInfo = IDLE_TURN
let isInteractive = true
const clients = new Set<string>()

/** True when a person can see this session: the REPL, or an app attached to it, such as the desktop app. */
function hasPerson(): boolean {
  return isInteractive || clients.size > 0
}
let turnFiles = new Set<string>()
let ticker: Timer | null = null
let ticks = 0
let lastHitAt = 0
// A subagent working on after the turn keeps the sky open this long after each of its tool calls, so the band does
// not fold and unfold between them.
const BACKGROUND_SKY_MS = 12_000
let backgroundUntil = 0
let focusDone: Timer | null = null
let storeQueue: Promise<unknown> = Promise.resolve()
let toastSlot = 0

// What the person is doing. The draft's text is never kept: only its length.
// hits: characters typed into this draft, each one a HIT. tier: its HIT tier. milestone: the last HIT count that went up as a word.
// jets: where the typing fountain leapt at the last keystrokes, so sparks already in the air stay where they rose.
type Jet = { at: number; x: number }
type Typing = { len: number; typed: number; hits: number; energy: number; lastAt: number; pips: number; tier: number; flashUntil: number; milestone: number; jets: readonly Jet[] }
const NO_TYPING: Typing = { len: 0, typed: 0, hits: 0, energy: 0, lastAt: 0, pips: 0, tier: 0, flashUntil: 0, milestone: 0, jets: [] }
let lastKeySoundAt = 0
// Where the next keystroke's effects go: steps of the golden ratio across the sky, so each key lands far from the last.
let typeSpin = 0
let typing: Typing = NO_TYPING
let ack: { label: string; color: string; until: number } | null = null
// Permission dialogs up and waiting on the person: the tool and its input as the dialog showed them. The call that
// comes back with the same tool and input is the one they answered.
let asking: Array<{ tool: string; input: unknown }> = []

/** The dialog's input and the call's own agree, field by field. */
function isSameCall(input: unknown, call: Record<string, unknown>): boolean {
  if (!input || typeof input !== 'object') return true
  return Object.entries(input as Record<string, unknown>).every(([k, v]) => JSON.stringify(v) === JSON.stringify(call[k]))
}

/** The dialog a finished call answered, taken off the list: the same tool and input, else the oldest for its tool. */
function takeAnswered(call: Record<string, unknown>): boolean {
  const tool = typeof call.tool === 'string' ? call.tool : ''
  let i = asking.findIndex((a) => a.tool === tool && isSameCall(a.input, call))
  if (i < 0) i = asking.findIndex((a) => a.tool === tool)
  if (i < 0) return false
  asking = asking.filter((_, j) => j !== i)
  return true
}

/** Read-modify-writes of saved data run one at a time, so two rewards landing together cannot overwrite each other. */
function serial<T>(fn: () => Promise<T>): Promise<T> {
  const run = storeQueue.then(fn, fn)
  storeQueue = run.catch(() => undefined)
  return run
}

/** Reward toasts land one after another, like a payout, each with its sound and fireworks. */
function queueToast($: Api, text: string, sound: string, occasion: Occasion, opts: ShowOptions = {}) {
  const now = Date.now()
  const at = Math.max(now, toastSlot)
  toastSlot = at + 700
  const land = () => {
    $.ui.toast(text, { timeoutMs: 4500 })
    sfx($, sound, 0.8)
    startShow($, occasion, opts)
  }
  if (at <= now) land()
  else $.clock.after(at - now, land)
}
