function sfx($: Api, name: string, gain = 0.8) {
  if (!settings.isOn || !settings.sfx || !hasPerson()) return
  // Not awaited: it resolves when the clip ends. A Linux or Windows terminal plays nothing.
  $.audio.play({ asset: `sfx/${name}.wav` }, { gain }).catch(() => {})
}

function ensureTicker($: Api) {
  if (ticker) return
  ticker = $.clock.every(FRAME_MS, () => onTick($))
}

function onTick($: Api) {
  ticks += 1
  const now = Date.now()
  const isShowing = show !== null && now < show.end
  if (show && !isShowing) {
    show = null
    waiting = []
    $.ui.invalidate('ui.render') // the sky folds away or settles back
  }
  const sky = skyRows(now)
  if (sky >= 3) blitSky($, now)
  if (ack && now >= ack.until) {
    ack = null
    $.ui.invalidate('ui.render')
  }
  if (live.isWorking && ticks % 75 === 0) void refreshUsage($) // keeps HP live mid-turn
  const isTyping = settings.typing && typing.len > 0 && now - typing.lastAt < 1500
  if (live.isWorking || isShowing || isTyping || ack !== null || sky >= 3) {
    if (ticks % 3 === 0) $.ui.invalidate('ui.render')
  } else {
    $.ui.invalidate('ui.render') // one last frame so the HUD settles
    ticker?.cancel()
    ticker = null
  }
}

