/**
 * Milestones Claude reaches for you, read from a shell command it ran and what that printed: a commit (git's
 * "[branch abc1234]" line), a push, a pull request opened (its URL) or merged. Reads only; runs nothing.
 */
export function readMoments(command: string, output: string, isError: boolean): Array<{ kind: Moment; word: string; detail: string }> {
  if (isError) return []
  const found: Array<{ kind: Moment; word: string; detail: string }> = []
  const commit = /\bgit\s+commit\b/.test(command) ? /\[[^\]\s]+(?: \([^)]*\))? ([0-9a-f]{7,40})\]/.exec(output) : null
  if (commit) found.push({ kind: 'commit', word: 'COMMIT', detail: commit[1]!.slice(0, 7) })
  if (/\bgit\s+push\b/.test(command) && !/rejected|error:|fatal:|Everything up-to-date/i.test(output)) found.push({ kind: 'push', word: 'PUSH', detail: '' })
  const pr = /\bgh\s+pr\s+create\b/.test(command) ? /https?:\/\/\S+\/pull\/(\d+)/.exec(output) : null
  if (pr) found.push({ kind: 'pr', word: `PR #${pr[1]}`, detail: `#${pr[1]}` })
  if (/\bgh\s+pr\s+merge\b/.test(command) && !/error|failed|not mergeable/i.test(output)) found.push({ kind: 'merge', word: 'MERGED', detail: '' })
  return found
}

// Claude's task list this session: created and done task ids. A task created after all were done starts a new list.
