  if (!Array.isArray(todos) || todos.length === 0) return
  const done = todos.filter((t) => (t as { status?: unknown })?.status === 'completed').length
  if (done > todoDone) onTaskDone($, done, todos.length)
  todoDone = done
}

const CHECKER = /\b(tsc|vue-tsc|eslint|ruff|mypy|pyright|biome|cargo (check|clippy|build)|javac|mvn|gradlew?|go (vet|build)|(npm|pnpm|yarn|bun) (run )?(lint|typecheck|type-check|check))\b/

/**
 * The error count a type checker or linter printed, or null when the command was not one or printed no count.
 * Reads tsc (its summary, or one line per error when piped) and mypy ("Found 12 errors in"), eslint ("12 errors"), ruff and biome ("Found 12 errors."), pyright,
 * cargo ("due to 12 previous errors") and javac ("12 errors"); a checker that ran clean and printed none is 0.
 */
export function readErrorCount(command: string, output: string, isError: boolean): number | null {
  if (!CHECKER.test(command)) return null
  const n = (re: RegExp) => {
    const m = re.exec(output)
    return m ? Number(m[1]) : null
  }
  // tsc prints its "Found N errors" summary only to a terminal; piped, it prints one line per error.
  const tscLines = (output.match(/^\S.*?(?:\(\d+,\d+\): error TS\d+|:\d+:\d+ - error TS\d+)/gm) ?? []).length
  return (
    n(/Found (\d+) errors? in /) ??
    (tscLines > 0 ? tscLines : null) ??
    n(/✖ \d+ problems? \((\d+) errors?/) ??
    n(/Found (\d+) errors?\./) ??
    n(/(\d+) errors?, \d+ warnings?, \d+ informations?/) ??
    n(/could not compile .* due to (\d+) previous errors?/) ??
    n(/^(\d+) errors?$/m) ??
    (!isError && !/\berror\b/i.test(output) ? 0 : null)
  )
}

// The last error count per command: only the same command run again is compared, so checking the whole project
// then one file never looks like progress.
const lastErrors = new Map<string, number>()

async function onErrorCount($: Api, command: string, ran: unknown) {
  const out = bashOutput(ran)
  if (!out) return
  const count = readErrorCount(command, out.text, out.isError)
  if (count === null) return
  const key = command.trim().replace(/\s+/g, ' ')
  const before = lastErrors.get(key)
  lastErrors.set(key, count)
  if (before === undefined || count >= before || !settings.isOn || !hasPerson()) return
  const fixed = before - count
  $.ui.toast(count === 0 ? `CLEAN  ${fixed} error${fixed === 1 ? '' : 's'} fixed` : `ERRORS  ${before} to ${count}`, { timeoutMs: 4500 })
  startShow($, count === 0 ? 'clean' : 'errors', { text: count === 0 ? '0 ERRORS' : `-${fixed} ERRORS` })
  await award($, Math.min(50, fixed * 5))
}

const MOMENT_XP: Record<Moment, number> = { commit: 30, push: 40, pr: 60, merge: 80 }
const MOMENT_TOAST: Record<Moment, string> = { commit: 'COMMIT', push: 'PUSHED', pr: 'PULL REQUEST OPENED', merge: 'MERGED' }

async function onMoments($: Api, command: string, ran: unknown) {
  const out = bashOutput(ran)
  if (!out) return
  for (const m of readMoments(command, out.text, out.isError)) {
    await serial(async () => {
      const p = normalizeProfile(await $.store.get('profile'))
      const next = { ...p, moments: { ...p.moments, [m.kind]: p.moments[m.kind] + 1 } }
      await $.store.set('profile', next)
      await update($, profileAtom, () => next)
    })
    await update($, statsAtom, (st) => ({ ...st, moments: { ...st.moments, [m.kind]: st.moments[m.kind] + 1 } }))
    if (!settings.isOn || !hasPerson()) continue
    $.ui.toast(`${MOMENT_TOAST[m.kind]}${m.detail ? `  ${m.detail}` : ''}  +${MOMENT_XP[m.kind]} XP`, { timeoutMs: 5000 })
    startShow($, m.kind, { text: m.word })
    await award($, MOMENT_XP[m.kind])
    if (m.kind === 'commit') await achieve($, 'commit')
    if (m.kind === 'merge') await achieve($, 'merged')
  }
}

