/** Context is HP: warn at 70, 85 and 95 percent used, cheer when it comes back. */
function ctxAlerts($: Api, used: number) {
  const prev = lastCtx
  lastCtx = used
  if (!alertsOn()) return
  const left = Math.max(0, 100 - used)
  if (prev !== null && used <= prev - 25) {
    $.ui.toast(`HP RECOVER  ${left}% of context free`, { timeoutMs: 4000 })
    sfx($, 'heal', 0.7)
    startShow($, 'heal')
    return
  }
  const crossed = [95, 85, 70].find((t) => used >= t && (prev === null ? t >= 85 : prev < t))
  if (crossed === 95) {
    $.ui.toast(`DANGER  context ${used}% full. Auto-compact is near`, { timeoutMs: 6000 })
    sfx($, 'warn', 0.7)
  } else if (crossed === 85) {
    $.ui.toast(`WARNING  context ${used}% full. Compact now`, { timeoutMs: 6000 })
    sfx($, 'warn', 0.7)
  } else if (crossed === 70) {
    $.ui.toast(`HP ${left}%  context ${used}% full. Wrap up or /compact`, { timeoutMs: 5000 })
  }
}

/** Plan limits are STAMINA: warn at 75, 90 and 100 percent used, cheer on a refill. */
function limitAlerts($: Api, limits: readonly Limit[]) {
  for (const l of limits) {
    const prev = lastLimits.get(l.kind)
    lastLimits.set(l.kind, l.percentUsed)
    if (!alertsOn()) continue
    const name = limitName(l.kind)
    const refill = untilText(l.resetsAt)
    const when = refill === 'now' ? ', refilling now' : refill ? `, refills in ${refill}` : ''
    if (prev !== undefined && l.percentUsed <= prev - 30) {
      $.ui.toast(`STAMINA RECOVER  ${name} limit back to ${l.percentUsed}% used`, { timeoutMs: 5000 })
      sfx($, 'heal', 0.8)
      startShow($, 'refill')
      continue
    }
    const crossed = [100, 90, 75].find((t) => l.percentUsed >= t && (prev === undefined ? t >= 90 : prev < t))
    if (crossed === 100) {
      $.ui.toast(`STAMINA EMPTY  ${name} limit used up${when}`, { timeoutMs: 8000 })
      sfx($, 'warn', 0.8)
    } else if (crossed === 90) {
      $.ui.toast(`STAMINA WARNING  ${name} limit ${l.percentUsed}% used${when}`, { timeoutMs: 6000 })
      sfx($, 'warn', 0.7)
    } else if (crossed === 75) {
      $.ui.toast(`STAMINA ${Math.max(0, Math.round(100 - l.percentUsed))}%  ${name} limit ${l.percentUsed}% used${when}`, { timeoutMs: 5000 })
    }
  }
}

