/** Text a shell call (Bash or PowerShell) printed, when it ran to the end in the foreground. */
// Color codes test runners and checkers print even when piped (Vitest does). Stripped before anything is read.
const ANSI = /\u001b\[[0-9;?]*[ -/]*[@-~]/g

function bashOutput(ran: unknown): { text: string; isError: boolean } | null {
  const r = ran as { result?: unknown; isError?: unknown; deny?: unknown }
  if (r.deny) return null
  if (typeof r.result === 'string') return { text: r.result.replace(ANSI, ''), isError: r.isError === true }
  const out = r.result as Record<string, unknown> | undefined
  if (!out || typeof out !== 'object' || out.interrupted === true || out.backgroundTaskId) return null
  const text = `${typeof out.stdout === 'string' ? out.stdout : ''}\n${typeof out.stderr === 'string' ? out.stderr : ''}`
  return { text: text.replace(ANSI, ''), isError: r.isError === true }
}

/** Looks at a finished shell call for a test summary or pull request checks. Reads only; runs nothing. */
async function readBash($: Api, command: string, ran: unknown) {
  const out = bashOutput(ran)
  if (!out) return
  if (TEST_COMMAND.test(command)) {
    await onTestRun($, parseTestOutput(out.text) ?? { passed: 0, failed: out.isError ? 1 : 0, isKnown: false })
  } else if (CHECKS_COMMAND.test(command)) {
    const checks = parseChecks(out.text)
    if (checks) await onChecks($, checks)
  }
}

async function onTestRun($: Api, count: TestCount) {
  if (count.isKnown && count.passed + count.failed === 0) return
  const isGreen = count.failed === 0
  const prev = await read($, testsAtom)
  const greenStreak = isGreen ? prev.greenStreak + 1 : 0
  const isComeback = isGreen && prev.wasRed
  await update($, testsAtom, () => ({ last: { ...count, isGreen, at: Date.now() }, greenStreak, wasRed: !isGreen }))
  if (!settings.isOn || !hasPerson()) return
  const tally = count.isKnown ? `${count.passed}/${count.passed + count.failed} passed` : 'passed'
  if (isComeback) {
    $.ui.toast(`COMEBACK  red to green, ${tally}`, { timeoutMs: 5000 })
    sfx($, 'jackpot', 0.8)
    startShow($, 'comeback')
    await award($, 80)
    await achieve($, 'comeback')
  } else if (isGreen) {
    sfx($, 'green', 0.5)
    if (greenStreak === 1 || greenStreak % 5 === 0) {
      $.ui.toast(`ALL GREEN  ${tally}${greenStreak > 1 ? `  ${greenStreak} in a row` : ''}`, { timeoutMs: 3500 })
    }
    const before = prev.last
    if (before?.isGreen && before.isKnown && count.isKnown && count.passed > before.passed) {
      startShow($, 'tests', { text: `+${count.passed - before.passed} TESTS` }) // the suite grew and stays green
    }
    await award($, 20)
    await achieve($, 'all-green')
  }
}

async function onChecks($: Api, c: CheckCount) {
  const prev = await read($, bossAtom)
  const isDefeated = c.total > 0 && c.failed === 0 && c.pending === 0
  await update($, bossAtom, () => ({ ...c, at: Date.now(), isDefeated }))
  if (!settings.isOn || !hasPerson()) return
