/** /dopa boss: runs `gh pr checks` once, only because you typed it. */
async function checkBoss($: Api) {
  let stdout = ''
  let stderr = ''
  try {
    const out = await $.process.run(['gh', 'pr', 'checks', '--json', 'name,bucket'], { timeoutMs: 20_000 })
    stdout = out.stdout
    stderr = out.stderr
  } catch (err) {
    $.ui.toast(`BOSS  could not run gh: ${err instanceof Error ? err.message : String(err)}`, { timeoutMs: 6000 })
    return
  }
  const checks = parseChecks(stdout)
  if (!checks) {
    const why = stderr.trim().split('\n')[0] ?? ''
    $.ui.toast(`BOSS  no checks found${why ? `: ${why}` : ''}`, { timeoutMs: 6000 })
    return
  }
  await onChecks($, checks)
}

async function listCommands($: Api) {
