/** /dopa daily: one command card a day from this install's own command list, so each description is accurate. */
async function drawDaily($: Api) {
  const today = localDay()
  const all = await listCommands($)
  if (all.length === 0) {
    $.ui.toast('DAILY CARD  no commands to draw from')
    return
  }
  const card = await serial(async () => {
    const dex = normalizeDex(await $.store.get('dex'))
    if (dex.day === today && dex.card) return { name: dex.card, isNew: !dex.captured.includes(dex.card), isFresh: false }
    const fresh = all.filter((c) => !dex.captured.includes(c.name))
    const pool = fresh.length > 0 ? fresh : all
    const name = pool[Math.floor(random01() * pool.length)]?.name ?? all[0]!.name
    await $.store.set('dex', { ...dex, day: today, card: name, isCardCaptured: dex.captured.includes(name) })
    return { name, isNew: !dex.captured.includes(name), isFresh: true }
  })
  if (card.isFresh) sfx($, 'coin', 0.7)
  const info = all.find((c) => c.name === card.name)
  const head = `DAILY CARD  /${card.name}${card.isNew ? '  NEW' : ''}`
  $.ui.log(head)
  if (info) $.ui.log(`  ${info.description}`)
  $.ui.log(card.isNew ? '  Run it today to capture it: +60 XP' : '  Already captured. A new card comes tomorrow')
  $.ui.toast(head, { timeoutMs: 4000 })
}

async function showDex($: Api) {
  const dex = normalizeDex(await $.store.get('dex'))
  const names = (await listCommands($)).map((c) => c.name)
  const missing = names.filter((n) => !dex.captured.includes(n))
  $.ui.log(`DEX  ${names.length - missing.length}/${names.length} commands captured`)
  if (missing.length > 0) {
    const more = missing.length > 24 ? `  +${missing.length - 24} more` : ''
    $.ui.log(`Not tried yet: ${missing.slice(0, 24).map((n) => `/${n}`).join('  ')}${more}`)
  }
}

/** The first time you run a command, it is captured. The daily card pays extra. */
/** Runs a command: a new one is captured for XP. Resolves to whether it was new. */
async function capture($: Api, name: string): Promise<boolean> {
  const result = await serial(async () => {
    const dex = normalizeDex(await $.store.get('dex'))
    if (dex.captured.includes(name)) return null
    const isDaily = dex.card === name && dex.day === localDay()
    const next = { ...dex, captured: [...dex.captured, name], isCardCaptured: dex.isCardCaptured || isDaily }
    await $.store.set('dex', next)
    return { isDaily, count: next.captured.length }
  })
  if (!result) return false
  const xp = result.isDaily ? 60 : 20
  $.ui.toast(`CAPTURED  /${name}${result.isDaily ? '  daily card' : ''}  +${xp} XP`, { timeoutMs: 4000 })
  sfx($, 'combo', 0.6)
  await award($, xp)
  if (result.count >= 10) await achieve($, 'dex-10')
  return true
}

function armFocus($: Api, f: NonNullable<FocusState>) {
  focusDone?.cancel()
  focusTick?.cancel()
  focusDone = $.clock.after(Math.max(0, f.endsAt - Date.now()), () => {
    void finishFocus($).catch(() => {})
  })
  focusTick = $.clock.every(1000, () => $.ui.invalidate('ui.render'))
}

function disarmFocus() {
  focusDone?.cancel()
  focusTick?.cancel()
  focusDone = null
  focusTick = null
}

async function startFocus($: Api, kind: 'focus' | 'break', minutes: number) {
  const f = { kind, minutes, endsAt: Date.now() + minutes * 60_000 }
  await update($, focusAtom, () => f)
  armFocus($, f)
  $.ui.toast(`${kind === 'focus' ? 'FOCUS' : 'BREAK'}  ${minutes} min on the clock`, { timeoutMs: 3000 })
}

async function stopFocus($: Api) {
  disarmFocus()
  const f = await read($, focusAtom)
  await update($, focusAtom, () => null)
  $.ui.toast(f?.kind === 'focus' ? 'FOCUS stopped, no XP this time' : 'Timer stopped', { timeoutMs: 3000 })
}

async function finishFocus($: Api) {
  const f = await read($, focusAtom)
  disarmFocus()
  if (!f) return
  await update($, focusAtom, () => null)
  if (!settings.isOn || !hasPerson()) return
  if (f.kind === 'break') {
    $.ui.toast('BREAK OVER  back to it', { timeoutMs: 5000 })
    sfx($, 'your-move', 0.8)
    return
  }
  const xp = f.minutes * 5
  $.ui.toast(`FOCUS CLEAR  ${f.minutes} min  +${fmt(xp)} XP`, { timeoutMs: 6000 })
  sfx($, 'trophy', 0.8)
  startShow($, 'focus')
  await award($, xp)
  const count = await serial(async () => {
    const day = localDay()
    const raw = (await $.store.get('focusDay')) as { day?: unknown; count?: unknown } | undefined
    const next = raw && raw.day === day && typeof raw.count === 'number' ? raw.count + 1 : 1
    await $.store.set('focusDay', { day, count: next })
    return next
  })
  await achieve($, 'focus-1')
  if (count >= 4) await achieve($, 'focus-4')
  $.clock.after(1500, () => $.ui.toast(count % 4 === 0 ? 'Long break earned: /dopa break 15' : 'Take five: /dopa break', { timeoutMs: 5000 }))
}

// ---------------------------------------------------------------- drawing helpers

/** Text in a ladder color; the rainbow step cycles letter by letter. */
function lamp(T: BoxText, text: string, level: number, phase: number, isInverse = false): RenderElement {
  if (level < 5) return T.Text({ color: LADDER[Math.max(0, level)]!, bold: true, inverse: isInverse, children: text })
  return T.Box({
    flexDirection: 'row',
    children: Array.from(text).map((ch, i) =>
      T.Text({ color: RAINBOW[(i + phase) % RAINBOW.length]!, bold: true, inverse: isInverse, children: ch }),
    ),
  })
}

type Piece = { width: number; priority: number; node: RenderElement }

function piece(width: number, priority: number, node: RenderElement): Piece {
  return { width, priority, node }
}

/** A piece held at `width` columns however short its text gets, so whatever follows it stays where it is. */
function slot(T: BoxText, width: number, priority: number, node: RenderElement): Piece {
  return piece(width, priority, T.Box({ minWidth: width, children: [node] }))
}

/** Lays pieces out in one row, dropping the least important until they fit. */
function fitRow(T: BoxText, pieces: Piece[], columns: number, gap = 3): RenderElement {
  const kept = pieces.slice()
  const width = () => kept.reduce((sum, p) => sum + p.width, 0) + gap * Math.max(0, kept.length - 1)
  while (kept.length > 1 && width() > columns) {
    let worst = 0
    kept.forEach((p, i) => {
      if (p.priority > kept[worst]!.priority) worst = i
    })
    kept.splice(worst, 1)
  }
  return T.Box({ flexDirection: 'row', columnGap: gap, children: kept.map((p) => p.node) })
}

function xpBar(p: Profile, width: number): string {
  const filled = Math.min(width, Math.round((p.xp / xpToNext(p.level)) * width))
  return `▕${'█'.repeat(filled)}${'░'.repeat(width - filled)}▏`
}

function streakColor(streak: number): string {
  return LADDER[Math.min(4, Math.floor(streak / 5))]!
}

/**
 * LV, the XP bar, the XP count and the rank, first in both rows at fixed widths. A file name, the HIT count or a
 * chip changing length used to push the XP about, and it should stay where the eye left it.
 */
function levelPieces(T: BoxText, p: Profile): Piece[] {
  const next = xpToNext(p.level)
  return [
    slot(T, 5, 0, T.Text({ bold: true, children: `LV ${p.level}` })),
    piece(14, 1, T.Text({ color: GOLD, children: xpBar(p, 12) })),
    // As wide as this level's fullest count, so the count filling up moves nothing either.
    slot(T, `${fmt(next)}/${fmt(next)} XP`.length, 3, T.Text({ dimColor: true, children: `${fmt(p.xp)}/${fmt(next)} XP` })),
    slot(T, 6, 5, T.Text({ dimColor: true, children: levelTitle(p.level) })),
  ]
}

/** What the person is doing: the typing badge while they write, and the chip for their last action. */
type Person = { typed: Piece | null; chip: Piece | null }
const NOBODY: Person = { typed: null, chip: null }

/** Between turns: the level block, the streak, the typing badge while you write (or the help hint), then the chip. */
function idleRow(T: BoxText, p: Profile, columns: number, person: Person = NOBODY): RenderElement {
  const pieces = levelPieces(T, p)
  if (p.streak >= 2) {
    const t = `STREAK ${p.streak}`
    pieces.push(piece(t.length, 2, T.Text({ color: streakColor(p.streak), bold: true, children: t })))
  }
  // The badge takes the hint's place while you write, so neither one moves anything.
  pieces.push(person.typed ?? piece(10, 6, T.Text({ dimColor: true, children: '/dopa help' })))
  if (person.chip) pieces.push(person.chip)
  return fitRow(T, pieces, columns)
}

// Room for " 999 HIT " and the longest tier word, the files count, and what Claude is touching.
const HITS_WIDTH = 19
const FILES_WIDTH = 8
const MOVE_WIDTH = 30

/** While Claude works: the level block, the hit count in its ladder color, the files this turn has edited, what it is touching. */
function feverRow(T: BoxText, turn: TurnInfo, p: Profile, columns: number, phase: number, now: number, person: Person = NOBODY): RenderElement {
  const tier = comboTier(turn.combo)
  const isHit = turn.combo > 0 && now - lastHitAt < 280
  const hits = turn.combo === 0 ? 'READY' : `${turn.combo} HIT`
  const files = turnFiles.size > 0 ? `${turnFiles.size} file${turnFiles.size === 1 ? '' : 's'}` : ''
  const pieces = levelPieces(T, p)
  pieces.push(
    slot(T, HITS_WIDTH, 0, T.Box({
      flexDirection: 'row',
      columnGap: 1,
      children: [
        turn.combo === 0 ? T.Text({ dimColor: true, children: ` ${hits} ` }) : lamp(T, ` ${hits} `, tier.level, phase, isHit),
        tier.word ? lamp(T, tier.word, tier.level, phase) : null,
      ],
    })),
    // Held open before the first edit too, so the move after it does not jump when a file lands.
    slot(T, FILES_WIDTH, 2, T.Text({ color: '#2ed47a', bold: isHit, children: files })),
  )
  pieces.push(slot(T, MOVE_WIDTH, 4, T.Text({ dimColor: true, children: turn.move })))
  if (person.typed) pieces.push(person.typed)
  if (person.chip) pieces.push(person.chip)
  return fitRow(T, pieces, columns)
}

function meterBar(left: number, width: number): string {
  const filled = Math.max(0, Math.min(width, Math.round((left / 100) * width)))
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

function gauge(T: BoxText, label: string, left: number, color: string, tail: string, isUrgent: boolean, priority: number): Piece {
  return piece(
    label.length + 10 + tail.length,
    priority,
    T.Box({
      flexDirection: 'row',
      children: [
        T.Text({ color, bold: true, inverse: isUrgent, children: label }),
        T.Text({ color, children: ` ${meterBar(left, 8)} ` }),
        isUrgent ? T.Text({ color, bold: true, children: tail }) : T.Text({ dimColor: true, children: tail }),
      ],
    }),
  )
}

/** HP (context left), STAMINA (plan limit left, with its refill), GOLD (cost), LOOT (files edited). */
function statusRow(T: BoxText, m: Meter | null, stats: SessionStats, columns: number, extra: RenderElement | null, more: Piece[] = []): RenderElement | null {
  const pieces: Piece[] = []
  if (m && m.ctxPercent !== null) {
    const left = Math.max(0, 100 - m.ctxPercent)
    const color = left >= 50 ? '#2ed47a' : left >= 25 ? GOLD : PINK
    const tail = m.ctxTokens !== null ? `${short(Math.max(0, m.ctxWindow - m.ctxTokens))} ctx left` : `${left}% ctx left`
    pieces.push(gauge(T, 'HP', left, color, tail, left < 15, 0))
  }
  const ranked = [...(m?.limits ?? [])].sort((a, b) => b.percentUsed - a.percentUsed)
  const binding = ranked[0]
  if (binding) {
    const left = Math.max(0, Math.round(100 - binding.percentUsed))
    const color = left >= 50 ? '#3d8bff' : left >= 20 ? ORANGE : PINK
    pieces.push(gauge(T, 'STAMINA', left, color, `${limitName(binding.kind, true)} limit ${left}% left`, left < 10, 1))
    const refill = untilText(binding.resetsAt)
    if (refill) {
      const t = refill === 'now' ? 'refilling now' : `refills in ${refill}`
      pieces.push(piece(t.length, 3, T.Text({ dimColor: true, children: t })))
    }
    for (const other of ranked.slice(1)) {
      const t = `${limitName(other.kind, true)} ${Math.max(0, Math.round(100 - other.percentUsed))}% left`
      pieces.push(piece(t.length, 5, T.Text({ dimColor: true, children: t })))
    }
  }
  if (m && m.usd !== null) {
    const t = `GOLD $${m.usd.toFixed(2)}`
    pieces.push(piece(t.length, 4, T.Text({ color: GOLD, children: t })))
  }
  const files = Object.keys(stats.files).length
  if (files > 0) {
    const t = `LOOT ${files} file${files === 1 ? '' : 's'} edited`
    pieces.push(piece(t.length, 6, T.Text({ color: '#2ed47a', children: t })))
  }
  pieces.push(...more)
  if (extra) pieces.push(piece(15, 0, extra))
  return pieces.length > 0 ? fitRow(T, pieces, columns) : null
}

function focusPiece(T: BoxText, f: FocusState, now: number): Piece | null {
  if (!f) return null
  const left = Math.max(0, f.endsAt - now)
  const t = `${f.kind === 'focus' ? 'FOCUS' : 'BREAK'} ${Math.floor(left / 60_000)}:${String(Math.floor((left % 60_000) / 1000)).padStart(2, '0')}`
  return piece(t.length, 1, T.Text({ color: f.kind === 'focus' ? GOLD : LADDER[1], bold: true, children: t }))
}

function testsPiece(T: BoxText, tests: TestState, now: number): Piece | null {
  const r = tests.last
  if (!r || now - r.at > 3 * 3_600_000) return null
  const t = r.isKnown ? `TESTS ${r.passed}/${r.passed + r.failed}` : `TESTS ${r.isGreen ? 'green' : 'red'}`
  return piece(t.length, r.isGreen ? 2 : 1, T.Text({ color: r.isGreen ? LADDER[2] : LADDER[3], bold: true, children: t }))
}

function bossPiece(T: BoxText, b: BossState | null, now: number): Piece | null {
  if (!b || now - b.at > 3 * 3_600_000) return null
  if (b.isDefeated) {
    const t = `CI ${b.passed}/${b.total} ✓`
    return piece(t.length, 4, T.Text({ color: LADDER[2], children: t }))
  }
  if (b.failed > 0) {
    const t = `CI ${b.failed} failed`
    return piece(t.length, 1, T.Text({ color: LADDER[3], bold: true, children: t }))
  }
  const width = Math.min(10, b.total)
  const hp = Math.max(1, Math.round((b.pending / b.total) * width))
  const t = `BOSS ▕${'█'.repeat(hp)}${'░'.repeat(width - hp)}▏ ${b.pending} left`
  return piece(t.length, 3, T.Text({ color: GOLD, bold: true, children: t }))
}

// ---------------------------------------------------------------- fireworks

function hash(a: number, b = 0): number {
  let h = Math.imul(a | 0, 374761393) ^ Math.imul(b | 0, 668265263)
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return (h ^ (h >>> 16)) >>> 0
}

function lerpColor(a: number, b: number, t: number): number {
  const ch = (shift: number) => Math.round(((a >> shift) & 255) + (((b >> shift) & 255) - ((a >> shift) & 255)) * t)
  return (ch(16) << 16) | (ch(8) << 8) | ch(0)
}

function toBase64(bytes: Uint8Array): string {
  const native = (bytes as unknown as { toBase64?: () => string }).toBase64
  if (typeof native === 'function') return native.call(bytes)
  let s = ''
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
  return btoa(s)
}

