function shellLife(s: Shell): number {
  return s.lifeMs ?? SHELL[s.kind].life
}

export function makeShow(occasion: Occasion, at: number, seed: number, opts: ShowOptions = {}): Show {
  const program = FW_PROGRAMS[occasion]
  const text = opts.text ?? program.text
  const start = (hash(seed, 99) % 1000) / 1000
  const hasWord = program.shells.some(([, kind]) => kind === 'text')
  const shells = program.shells.map(([offset, kind, color, fixedX], i): Shell => {
    const h = hash(seed, i)
    const u = (start + i * 0.618034) % 1 // golden-ratio spacing: each shell lands far from the last
    // A word goes in the middle and the other shells take the sides, so it stays readable.
    const x = opts.x ?? fixedX ?? (kind === 'text' || NO_RISE.has(kind) ? 0.5 : program.shells.length === 1 ? 0.12 + start * 0.76 : hasWord ? (u < 0.5 ? 0.03 + u * 0.46 : 0.74 + (u - 0.5) * 0.46) : 0.08 + 0.84 * u)
    const apex = kind === 'text' ? 0.5 : 0.28 + (((h >>> 10) % 100) / 100) * 0.17
    const shell: Shell = { at: at + offset, x, apex, kind, colors: FW_COLORS[opts.palette ?? color] ?? [0xffffff], seed: h }
    if (kind === 'strobe') shell.lifeMs = (opts.holdMs ?? 1400) + 700
    if (kind === 'text') {
      if (text) shell.text = text
      const holdMs = opts.holdMs ?? 900
      shell.holdMs = holdMs
      shell.lifeMs = 300 + holdMs + 800
      if (program.isStrobe) shell.isStrobe = true
    }
    return shell
  })
  const end = Math.max(...shells.map((s) => s.at + (NO_RISE.has(s.kind) ? 0 : RISE_MS) + shellLife(s)))
  return { at, end, rows: program.rows, shells }
}

