/** Every character a firework can spell. */
export const FONT_CHARS = Object.keys(FONT).join('')
const wordCache = new Map<string, ReadonlyArray<readonly [number, number]>>()
/** The dots of a word, centered on 0,0, each font pixel a size-by-size block. */
function wordDots(word: string, size: number): ReadonlyArray<readonly [number, number]> {
  const key = `${word}:${size}`
  const cached = wordCache.get(key)
  if (cached) return cached
  const glyphs = [...word].map((ch) => FONT[ch] ?? [])
  const width = glyphs.length * 6 * size - size
  const dots: Array<readonly [number, number]> = []
  glyphs.forEach((rows, g) => {
    rows.forEach((line, ry) => {
      for (let rx = 0; rx < 5; rx++) {
        if (line[rx] !== '#') continue
        for (let dy = 0; dy < size; dy++) for (let dx = 0; dx < size; dx++) dots.push([g * 6 * size + rx * size + dx - width / 2, ry * size + dy - (7 * size) / 2])
      }
    })
  })
  wordCache.set(key, dots)
  return dots
}

// The shortest sky a word is drawn in, in rows. Shorter, its letters come out a dot per pixel and read as a glitch,
// so the band gives the sky its frame and the meters row before it gets this short, and a sky shorter still
// shows its bursts without the word (the toast still says it).
const WORD_ROWS = 5

/** How big a word is drawn in a W by H sky: font pixels as size-by-size blocks, as large as fits 80% of the width. */
function wordSize(text: string, W: number, H: number): { size: number; width: number; height: number } {
  let size = Math.min(4, Math.max(1, Math.floor((H - 4) / 7)))
  while (size > 1 && text.length * 6 * size > W * 0.8) size -= 1
  return { size, width: [...text].length * 6 * size - size, height: 7 * size }
}

// Room kept clear around a word, in dots. A braille cell is 2 dots wide and 4 tall and a word's sparks gather from
// 3 dots out, so no other spark shares a cell with a letter and changes its color.
const CLEAR_X = 6
const CLEAR_Y = 5
type Clearing = { shell: Shell; x0: number; x1: number; y0: number; y1: number }

/**
 * The newest word in the sky and the box kept clear around it, from when its sparks gather until it has fallen.
 * Other sparks mixed into the letters made words hard to read, so nothing else is drawn there.
 */
function wordClearing(show: Show, now: number, W: number, H: number): Clearing | null {
  if (H < WORD_ROWS * 4) return null // no word is drawn in a sky this short
  let found: Clearing | null = null
  for (const s of show.shells) {
    if (s.kind !== 'text' || !s.text) continue
    const tau = (now - s.at - RISE_MS) / 1000
    if (tau < 0 || tau > shellLife(s) / 1000 || (found && found.shell.at >= s.at)) continue
    const { width, height } = wordSize(s.text, W, H)
    const x = s.x * (W - 1)
    const y = s.apex * H
    const fall = Math.max(0, tau - 0.3 - (s.holdMs ?? 900) / 1000)
    const drop = 0.5 * SHELL.text.gravity * (H / 32) * 1.1 * fall * fall // as far as its fastest letter has fallen
    found = { shell: s, x0: x - width / 2 - CLEAR_X, x1: x + width / 2 + CLEAR_X, y0: y - height / 2 - CLEAR_Y, y1: y + height / 2 + drop + CLEAR_Y }
  }
  return found
}

/** An emit that drops whatever would land in the clearing. */
function around(room: Clearing | null, emit: Emit): Emit {
  if (!room) return emit
  return (x, y, b, c) => {
    if (x < room.x0 || x > room.x1 || y < room.y0 || y > room.y1) emit(x, y, b, c)
  }
}

/** The white-hot flash where a shell opens. */
function bloom(x0: number, y0: number, tau: number, color: number, k: number, emit: Emit) {
  const r = (2 + 40 * tau) * k
  const c = lerpColor(0xffffff, color, tau / 0.14)
  for (let dy = -Math.ceil(r); dy <= r; dy++) {
    for (let dx = -Math.ceil(r * 1.5); dx <= r * 1.5; dx++) if ((dx / 1.5) ** 2 + dy * dy <= r * r) emit(x0 + dx, y0 + dy, 1 - tau / 0.14, c)
  }
}

/** A haze of dim sparks around a fresh burst: the glow, on any terminal background. */
function haze(s: Shell, x0: number, y0: number, tau: number, k: number, emit: Emit) {
  const spec = SHELL[s.kind]
  const r = spec.speed * k * ((1 - Math.exp(-spec.drag * tau)) / spec.drag) * 1.15
  for (let i = 0; i < 36; i++) {
    const h = hash(s.seed ^ 0x5bd1, i + Math.floor(tau * 30) * 37)
    const a = ((h % 1000) / 1000) * Math.PI * 2
    const d = Math.sqrt(((h >>> 10) % 1000) / 1000) * r
    emit(x0 + Math.cos(a) * d * 1.5, y0 + Math.sin(a) * d * 0.85, 0.2 * (1 - tau / 0.5), s.colors[0] ?? 0xffffff)
  }
}

/** Kata-mono: sparks fly out into a word, hang there glittering (or strobing, when a show asks), then fall. */
function word(s: Shell, x0: number, y0: number, tau: number, W: number, H: number, emit: Emit) {
  const text = s.text ?? ''
  if (H < WORD_ROWS * 4) return
  const hold = (s.holdMs ?? 900) / 1000
  const { size } = wordSize(text, W, H)
  const isRainbow = s.colors.length > 3
  const strobe = s.isStrobe ? (Math.floor(tau * 10) % 2 === 0 ? 1 : 0.3) : 1
  wordDots(text, size).forEach(([dx, dy], i) => {
    const h = hash(s.seed, i)
    let x = x0 + dx
    let y = y0 + dy
    let b = 1
    if (tau < 0.3) {
      const p = 1 - (1 - tau / 0.3) ** 3
      x = x0 + dx * p + ((h % 7) - 3) * (1 - p)
      y = y0 + dy * p + (((h >>> 3) % 7) - 3) * (1 - p)
    } else if (tau < 0.3 + hold) {
      b = strobe * (hash(h, Math.floor(tau * 16)) % 6 === 0 ? 0.35 : 1) // glitter
    } else {
      const f = tau - 0.3 - hold
      y += 0.5 * SHELL.text.gravity * (H / 32) * (0.6 + ((h >>> 6) % 50) / 100) * f * f
      b = Math.max(0, 1 - f / 0.8) * (hash(h, Math.floor(tau * 20)) % 3 === 0 ? 0.3 : 1)
    }
    if (b <= 0.04) return
    const color = isRainbow
      ? (s.colors[Math.floor((dx + 999 + tau * 60) / 5) % s.colors.length] ?? 0xffffff) // a rainbow that sweeps across the word
      : hash(h, Math.floor(tau * 10)) % 5 === 0 ? 0xffffff : (s.colors[0] ?? 0xffffff)
    emit(x, y, b, tau < 0.08 ? 0xffffff : color)
  })
}

/** Niagara: a curtain of gold sparks pouring down across the whole sky. */
function niagara(s: Shell, tau: number, W: number, H: number, emit: Emit) {
  if (tau > SHELL.niagara.life / 1000) return
  const k = H / 32
  for (let ex = 1; ex < W; ex += 3) {
    for (let n = 0; n < 19; n++) {
      const a = tau - n * 0.07 - ((ex / 3) % 3) * 0.02
      if (a < 0 || a > 0.9) continue
      const y = 1 + 5 * k * a + 0.5 * SHELL.niagara.gravity * k * a * a
      if (y >= H) continue
      const h = hash(s.seed + ex, n)
      const b = (1 - a / 0.9) * (0.55 + 0.45 * ((h % 100) / 100)) * (hash(h, Math.floor(tau * 20)) % 4 === 0 ? 0.3 : 1)
      emit(ex + Math.sin(n + ex) * 0.6, y, b, n % 4 === 0 ? 0xffffff : (s.colors[(n + ex) % s.colors.length] ?? 0xffc928))
    }
  }
}

/** Bunpo: six stars fly out with trails, then each splits into five crossing sparks. */
function crossette(s: Shell, x0: number, y0: number, tau: number, k: number, life: number, emit: Emit) {
  const spec = SHELL.cross
  const reach = (tt: number) => (1 - Math.exp(-spec.drag * tt)) / spec.drag
  const split = 0.32
  for (let i = 0; i < spec.count; i++) {
    const h = hash(s.seed, i)
    const angle = (i / spec.count) * Math.PI * 2 + ((h % 100) / 100 - 0.5) * 0.3
    const vx = Math.cos(angle) * spec.speed * k * 1.5
    const vy = Math.sin(angle) * spec.speed * k * 0.85
    const color = s.colors[i % s.colors.length] ?? 0xffffff
    const px = (tt: number) => x0 + vx * reach(tt)
    const py = (tt: number) => y0 + vy * reach(tt) + 0.5 * spec.gravity * k * tt * tt
    if (tau < split) {
      spec.echoes.forEach((back, e) => {
        const tt = tau - back
        if (tt >= 0) emit(px(tt), py(tt), ECHO_LIGHT[e] ?? 0.3, tt < 0.06 ? 0xffffff : color)
      })
      continue
    }
    const t2 = tau - split
    const life2 = life - split
    if (t2 > life2) continue
    const r2 = (1 - Math.exp(-2.8 * t2)) / 2.8
    for (let c = 0; c < 5; c++) {
      const a2 = angle + (c - 2) * 0.45
      let b = (1 - t2 / life2) ** 1.1
      if (hash(h + c, Math.floor(t2 * 20)) % 3 === 0) b *= 0.3
      emit(px(split) + Math.cos(a2) * 12 * k * 1.5 * r2, py(split) + Math.sin(a2) * 12 * k * 0.85 * r2 + 0.5 * spec.gravity * k * t2 * t2, b, c % 2 === 0 ? color : 0xffffff)
    }
  }
}

/** Funshutsu: a ground fountain, a jet of sparks from the bottom of the sky. */
function fountain(s: Shell, tau: number, W: number, H: number, emit: Emit) {
  const life = SHELL.fountain.life / 1000
  if (tau > life) return
  const x0 = s.x * (W - 1)
  const step = 0.02
  const spark = 0.6
  const last = Math.floor((life - spark) / step)
  for (let j = Math.max(0, Math.floor((tau - spark) / step)); j <= Math.min(last, Math.floor(tau / step)); j++) {
    for (let m = 0; m < 2; m++) {
      const age = tau - j * step
      const h = hash(s.seed + m * 977, j)
      const angle = -Math.PI / 2 + (((h >>> 3) % 1000) / 1000 - 0.5) * 0.6
      const speed = H * 2.3 * (0.8 + ((h >>> 13) % 100) / 250)
      const b = (1 - age / spark) * (hash(h, Math.floor(age * 20)) % 4 === 0 ? 0.4 : 1)
      emit(x0 + Math.cos(angle) * speed * age * 1.3, H - 1 + Math.sin(angle) * speed * age + 1.5 * H * age * age, b, age < 0.05 ? 0xffffff : (s.colors[(j + (h >>> 20)) % s.colors.length] ?? 0xffffff))
    }
  }
}

/** Kinpun: gold glitter that twinkles and drifts down across the whole sky. */
function glitter(s: Shell, tau: number, W: number, H: number, emit: Emit) {
  if (tau > SHELL.glitter.life / 1000) return
  const k = H / 32
  const count = Math.floor((W * H) / 40)
  for (let i = 0; i < count; i++) {
    const h = hash(s.seed, i)
    const age = tau - ((h % 1000) / 1000) * 0.8
    if (age < 0 || age > 1.2) continue
    const y = ((h >>> 20) % Math.max(1, Math.floor(H * 0.5))) + 6 * k * age + 3 * k * age * age
    if (y >= H) continue
    const b = (1 - age / 1.2) * (hash(h, Math.floor(age * 12)) % 3 === 0 ? 1 : 0.35)
    emit((h >>> 10) % W, y, b, (h >>> 5) % 4 === 0 ? 0xffffff : (s.colors[(h >>> 7) % s.colors.length] ?? 0xffc928))
  }
}

/** A strobing sky: points flash on and off all over, like camera flashes for a new pull request. */
function strobe(s: Shell, tau: number, W: number, H: number, emit: Emit) {
  if (tau > shellLife(s) / 1000) return
  const frame = Math.floor(tau * 12)
  const count = Math.floor((W * H) / 30)
  for (let i = 0; i < count; i++) {
    const h = hash(s.seed, i)
    if (hash(h, frame) % 4 === 0) emit(h % W, (h >>> 12) % H, 0.9, (h >>> 7) % 3 === 0 ? 0xffffff : (s.colors[0] ?? 0xff4545))
  }
}

/**
 * Every lit dot of a show at `now`, in dot coordinates of a W by H sky. Pure: any frame, any time. Around the word
 * that is up, only its own sparks are drawn, and the shell of the next word on its way up.
 */
function showDots(show: Show, now: number, W: number, H: number, raw: Emit, room = wordClearing(show, now, W, H)) {
  const k = H / 32
  const masked = around(room, raw)
  for (const s of show.shells) {
    const t = now - s.at
    if (t < 0) continue
    const emit = s.kind === 'text' && (t < RISE_MS || s === room?.shell) ? raw : masked
    if (s.kind === 'niagara') {
      niagara(s, t / 1000, W, H, emit)
      continue
    }
    if (s.kind === 'fountain') {
      fountain(s, t / 1000, W, H, emit)
      continue
    }
    if (s.kind === 'glitter') {
      glitter(s, t / 1000, W, H, emit)
      continue
    }
    if (s.kind === 'strobe') {
      strobe(s, t / 1000, W, H, emit)
      continue
    }
    const x0 = s.x * (W - 1)
    const y0 = s.apex * H
    if (t < RISE_MS) {
      const y = H - 1 - (H - 1 - y0) * (1 - (1 - t / RISE_MS) ** 2)
      emit(x0, y, 1, 0xfff3d0)
      emit(x0, y + 1.5, 0.55, 0xffc080)
      emit(x0, y + 3, 0.3, 0xff9a40)
      continue
    }
    const spec = SHELL[s.kind]
    const tau = (t - RISE_MS) / 1000
    const life = shellLife(s) / 1000
    if (tau > life) continue
    if (tau < 0.14) bloom(x0, y0, tau, s.colors[0] ?? 0xffffff, k, emit)
    if (s.kind === 'text') {
      word(s, x0, y0, tau, W, H, emit)
      continue
    }
    if (tau < 0.5) haze(s, x0, y0, tau, k, emit)
    if (s.kind === 'cross') {
      crossette(s, x0, y0, tau, k, life, emit)
      continue
    }
    const reach = (tt: number) => (1 - Math.exp(-spec.drag * tt)) / spec.drag
    // yae: an outer layer whose stars change color halfway, and an inner core.
    const layers: ReadonlyArray<readonly [number, number, number]> = s.kind === 'yae' ? [[spec.count, 1, 0], [Math.round(spec.count * 0.55), 0.5, 2]] : [[spec.count, 1, -1]]
    for (const [count, speedK, colorAt] of layers) {
      for (let i = 0; i < count; i++) {
        const h = hash(s.seed + colorAt * 7919, i)
        const angle = (i / count) * Math.PI * 2 + (spec.jitter ? ((h % 100) / 100 - 0.5) * 0.4 : 0)
        const speed = spec.speed * k * speedK * (1 + (spec.jitter ? (((h >>> 8) % 100) / 100 - 0.5) * 2 * spec.jitter : 0))
        const vx = Math.cos(angle) * speed * 1.5
        const vy = Math.sin(angle) * speed * 0.85
        const base = colorAt >= 0 ? (s.colors[colorAt] ?? 0xffffff) : (s.colors[(i + (h >>> 16)) % s.colors.length] ?? 0xffffff)
        spec.echoes.forEach((back, e) => {
          const tt = tau - back
          if (tt < 0) return
          const color = s.kind === 'yae' && colorAt === 0 && tt > life * 0.5 ? (s.colors[1] ?? base) : base
          let b = (1 - tt / life) ** 1.2 * (ECHO_LIGHT[e] ?? 0.15)
          if (spec.isCrackle && hash(h, Math.floor(tt * 20)) % 3 === 0) b *= 0.25
          if (b > 0.04) emit(x0 + vx * reach(tt), y0 + vy * reach(tt) + 0.5 * spec.gravity * k * tt * tt, b, tt < 0.08 ? lerpColor(0xffffff, color, tt / 0.08) : color)
        })
      }
    }
  }
}

const BRAILLE = [
  [0x01, 0x02, 0x04, 0x40],
  [0x08, 0x10, 0x20, 0x80],
] as const

/** Dots into Raster cells: braille, each cell in the color of its brightest spark, on the terminal's own background. */
function paintDots(cols: number, rows: number, draw: (emit: Emit) => void): string {
  const W = cols * 2
  const H = rows * 4
  const n = cols * rows
  const bits = new Uint8Array(n)
  const bright = new Float32Array(n)
  const color = new Uint32Array(n)
  const plot = (ix: number, iy: number, b: number, c: number) => {
    if (ix < 0 || ix >= W || iy < 0 || iy >= H) return
    const cell = (iy >> 2) * cols + (ix >> 1)
    bits[cell] = (bits[cell] ?? 0) | (BRAILLE[ix & 1]?.[iy & 3] ?? 0)
    if (b > (bright[cell] ?? 0)) {
      bright[cell] = b
      color[cell] = c
    }
  }
  draw((x, y, b, c) => {
    const ix = Math.round(x)
    const iy = Math.round(y)
    plot(ix, iy, b, c)
    if (b > 0.6) plot(ix + 1, iy, b * 0.9, c) // a bright star is two dots wide
  })
  const words = new Uint32Array(n * 3)
  for (let i = 0; i < n; i++) {
    const on = bits[i] ?? 0
    words[i * 3] = on ? 0x2800 | on : 0x20
    words[i * 3 + 1] = on ? lerpColor(0x1a1626, color[i] ?? 0xffffff, 0.35 + 0.65 * Math.min(1, bright[i] ?? 0)) : 0x01000000
    words[i * 3 + 2] = 0x01000000
  }
  return toBase64(new Uint8Array(words.buffer))
}

/** A show at `now` as Raster cells. */
export function paintShow(show: Show, now: number, cols: number, rows: number): string {
  return paintDots(cols, rows, (emit) => showDots(show, now, cols * 2, rows * 4, emit))
}

/** A show at `now` as an SVG frame, for the desktop app, which has no Raster. */
export function showSvg(show: Show, now: number, width: number, rows: number): string {
  return svgDots(width, rows, (emit) => showDots(show, now, 200, rows * 4, emit))
}

function svgDots(width: number, rows: number, draw: (emit: Emit) => void): string {
  const W = 200
  const H = rows * 4
  const pitch = width / W
  const height = Math.round(H * pitch)
  const dots: string[] = []
  draw((x, y, b, c) => {
    if (x < 0 || x > W || y < 0 || y > H || dots.length >= 1400) return
    dots.push(`<circle cx="${(x * pitch).toFixed(1)}" cy="${(y * pitch).toFixed(1)}" r="${(pitch * 0.45).toFixed(1)}" fill="#${c.toString(16).padStart(6, '0')}" opacity="${Math.min(1, b).toFixed(2)}"/>`)
  })
  const frame = `<rect x="0.5" y="0.5" width="${width - 1}" height="${height - 1}" rx="8" fill="none" stroke="#8a8698" stroke-opacity="0.55"/>`
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${frame}${dots.join('')}</svg>`
}

/** Typing HITs: every character you type is a HIT, with the tool-call tiers at typing speed. */
const TYPE_HIT_TIERS = [
  { at: 200, word: 'RAINBOW', level: 5 },
  { at: 100, word: 'FEVER', level: 4 },
  { at: 50, word: 'EXCELLENT', level: 3 },
  { at: 25, word: 'GREAT', level: 2 },
  { at: 10, word: 'GOOD', level: 1 },
  { at: 0, word: '', level: 0 },
] as const
export function typeHitTier(hits: number) {
  return TYPE_HIT_TIERS.find((t) => hits >= t.at) ?? TYPE_HIT_TIERS[TYPE_HIT_TIERS.length - 1]!
}
/** The last HIT count to go up as a word: 10, 25, 50, 100, 200, then every 100. */
export function typeHitMilestone(hits: number): number {
  if (hits >= 200) return Math.floor(hits / 100) * 100
  return [100, 50, 25, 10].find((m) => hits >= m) ?? 0
}
const KEY_SHOWS = ['key0', 'key1', 'key2', 'key3', 'key4', 'key5'] as const
const HIT_WORD_SHOWS = ['hitWord1', 'hitWord1', 'hitWord1', 'hitWord2', 'hitWord3', 'hitWord3'] as const
const TYPE_SKY_ROWS = [6, 6, 7, 7, 8, 8] as const
const TIER_PALETTE = ['white', 'blue', 'green', 'red', 'gold', 'rainbow'] as const
const KEY_COLORS = ['red', 'gold', 'green', 'blue', 'pinkBlue', 'goldRed', 'goldGreen'] as const

/**
 * Where a keystroke's effects go across the sky, 0 to 1, for a step `u` of the spin: anywhere, or out to the sides
 * while a word hangs in the middle. The mod cannot see where the prompt box draws the cursor, so nothing follows it.
 */
export function typeSpot(u: number, isWordUp: boolean): number {
  return isWordUp ? (u < 0.5 ? 0.04 + u * 0.44 : 0.74 + (u - 0.5) * 0.44) : 0.06 + 0.88 * u
}

// A keystroke sprays for this long. Sparks that kept rising while nobody typed looked like a glitch, so the
// fountain runs only while keys land and is out within a second of the last one.
const SPRAY_MS = 450

/**
 * Funshutsu while you type: a fountain of sparks in the color of the HIT tier that leaps to a new spot at every
 * keystroke (`jets`), its sparks already in the air staying where they rose. The faster you type, the higher and
 * thicker it shoots, and hard typing forks its sparks into pine needles.
 */
export function typingFountain(now: number, W: number, H: number, jets: readonly Jet[], energy: number, emit: Emit, tier = 0) {
  const palette = FW_COLORS[TIER_PALETTE[tier] ?? 'white'] ?? [0xffffff]
  const speedUp = H * (1.1 + 1.4 * energy)
  const rate = 0.25 + 0.75 * energy
  const life = 0.45 + 0.35 * energy
  const slot = Math.floor(now / 20)
  /** The keystroke the fountain was spraying for at `ms`, if any. */
  const sprayAt = (ms: number): Jet | null => {
    let last: Jet | null = null
    for (const j of jets) if (j.at <= ms) last = j
    return last && ms - last.at < SPRAY_MS ? last : null
  }
  // From EXCELLENT on, fountains at both ends of the sky join the leaping one.
  const sources: ReadonlyArray<number | null> = tier >= 3 ? [null, 0.04, 0.96] : [null]
  sources.forEach((fixed, jet) => {
    for (let n = 0; n < 40; n++) {
      const sl = slot - n
      const h = hash(sl + jet * 7919, 31)
      if ((h % 1000) / 1000 > rate) continue
      const age = (now - sl * 20) / 1000
      if (age > life) continue
      const from = sprayAt(sl * 20)
      if (!from) continue
      const x0 = (fixed ?? from.x) * (W - 1)
      const angle = -Math.PI / 2 + (((h >>> 3) % 1000) / 1000 - 0.5) * 0.7
      const speed = speedUp * (0.75 + ((h >>> 13) % 100) / 200)
      const x = x0 + Math.cos(angle) * speed * age * 1.3
      const y = H - 1 + Math.sin(angle) * speed * age + 1.5 * H * age * age
      const b = 1 - age / life
      const color = age < 0.06 ? 0xffffff : (palette[(h >>> 20) % palette.length] ?? 0xffffff)
      emit(x, y, b, color)
      if (energy > 0.5 && age > life * 0.5) for (const f of [-1, 1]) emit(x + f * 1.5, y + 1, b * 0.6, color)
    }
  })
  const nozzle = sprayAt(now)
  if (!nozzle) return
  const base = nozzle.x * (W - 1)
  emit(base, H - 1, 0.9, 0xffd27a)
  emit(base + 1, H - 1, 0.9, 0xffb050)
}

let show: Show | null = null
let bandRequestId: string | null = null
let bandCols = 0
let bandRows = 0
let isBlitBusy = false

// Words that must show the moment they happen: they cut in. The rest wait their turn, briefly.
const URGENT: ReadonlySet<Occasion> = new Set<Occasion>(['clear0', 'clear1', 'clear2', 'clear3', 'clear4', 'clear5', 'commit', 'push', 'pr', 'merge', 'go1', 'go2', 'go3', 'answer', 'preview', 'paste', 'hitWord1', 'hitWord2', 'hitWord3'])
const MAX_WAIT_MS = 3000
// An urgent word cuts in, but not before the word it cuts has been up this long, so a YES, the COMMIT and the PUSH one
// command earns all land, one after another, instead of only the last.
const MIN_READ_MS = 800
let waiting: Array<{ timer: Timer | null; shells: Shell[]; isUrgent: boolean }> = []

function wordFallsAt(sh: Shell): number {
  return sh.at + RISE_MS + 300 + (sh.holdMs ?? 900)
}

/**
 * Where a new show's word goes in line, so one word hangs at a time. Pure. An urgent word goes up as soon as the word
 * in the sky has been read for MIN_READ_MS, cutting its hold short; any other word waits for it to fall. A word that
 * would wait longer than MAX_WAIT_MS goes up without its word (the bursts still fly, the toast still says it).
 * Returns the shells already up, the new show's (moved later when it waits) and how long it waits.
 */
export function lineUp(current: readonly Shell[], incoming: readonly Shell[], now: number, isUrgent: boolean): { current: Shell[]; incoming: Shell[]; delay: number } {
  const firstWord = incoming.find((sh) => sh.kind === 'text')
  const words = current.filter((sh) => sh.kind === 'text' && wordFallsAt(sh) > now)
  if (!firstWord || words.length === 0) return { current: [...current], incoming: [...incoming], delay: 0 }
  const newest = words.reduce((a, b) => (b.at > a.at ? b : a))
  const freeAt = isUrgent ? Math.max(now, newest.at + RISE_MS + 300 + MIN_READ_MS) : Math.max(...words.map(wordFallsAt))
  const delay = Math.max(0, freeAt + 150 - (firstWord.at + RISE_MS))
  if (delay > MAX_WAIT_MS) return { current: [...current], incoming: incoming.filter((sh) => sh.kind !== 'text'), delay: 0 }
  const kept = !isUrgent
    ? [...current]
    : current.map((sh) => {
        if (sh.kind !== 'text' || wordFallsAt(sh) <= freeAt) return sh
        const holdMs = Math.max(0, freeAt - (sh.at + RISE_MS + 300))
        return { ...sh, holdMs, lifeMs: 300 + holdMs + 800 }
      })
  return { current: kept, incoming: delay > 0 ? incoming.map((sh) => ({ ...sh, at: sh.at + delay })) : [...incoming], delay }
}

const MAX_SHELLS = 32

/**
 * The shells a show keeps: the ones not yet over, at most 32, the oldest bursts dropping first. A word is never
 * dropped, or fast typing would push it out of the sky before it falls.
 */
export function keepShells(shells: readonly Shell[], now: number): Shell[] {
  const alive = shells.filter((sh) => now < sh.at + (NO_RISE.has(sh.kind) ? 0 : RISE_MS) + shellLife(sh))
  let drop = alive.length - MAX_SHELLS
  return alive.filter((sh) => {
    if (drop <= 0 || sh.kind === 'text') return true
    drop -= 1
    return false
  })
}

/**
 * Lights up the band. A show that starts while another runs joins it. Only one word hangs in the sky at a time
 * (lineUp): an urgent word (a finished turn, a commit or push, GO!, an answer) cuts in once the hanging word has been
 * read, so several landing together go up in turn; any other word waits for the last to fall. A word that would wait
 * more than 3 seconds gives up its word and keeps its bursts.
 */
function startShow($: Api, occasion: Occasion, opts: ShowOptions = {}) {
  if (!settings.isOn || !settings.fireworks || !hasPerson()) return
  const now = Date.now()
  const next = makeShow(occasion, now, Math.floor(random01() * 2 ** 31), opts)
  let shells = next.shells
  let delay = 0
  const isUrgent = URGENT.has(occasion)
  if (show && now < show.end) {
    let current = show.shells
    if (isUrgent) {
      // Words only waiting their turn give way, sounds and all (their toasts still say it); urgent words already in
      // line keep their place.
      const giving = waiting.filter((w) => !w.isUrgent)
      const dropped = new Set(giving.flatMap((w) => w.shells))
      giving.forEach((w) => w.timer?.cancel())
      waiting = waiting.filter((w) => w.isUrgent)
      current = current.filter((sh) => !dropped.has(sh))
    }
    const lined = lineUp(current, shells, now, isUrgent)
    current = lined.current
    shells = lined.incoming
    delay = lined.delay
    const end = Math.max(...[...current, ...shells].map((sh) => sh.at + (NO_RISE.has(sh.kind) ? 0 : RISE_MS) + shellLife(sh)))
    show = { at: show.at, end, rows: Math.max(show.rows, next.rows), shells: keepShells([...current, ...shells], now) }
  } else {
    show = next
    waiting = []
  }
  const sound = FW_SOUND[occasion]
  if (sound) {
    if (delay > 0) waiting.push({ timer: $.clock.after(delay, () => sfx($, sound, 1)), shells, isUrgent })
    else sfx($, sound, 1)
  } else if (delay > 0) {
    waiting.push({ timer: null, shells, isUrgent })
  }
  ensureTicker($)
  $.ui.invalidate('ui.render')
}

/** The typing sky stays open for a few seconds after a key, so a pause between words does not fold it away. */
function isSparkling(now: number): boolean {
  return settings.typing && typing.len > 0 && now - typing.lastAt < 4_000
}

/** How tall the sky wants to be now: the show's height, 6 rows while Claude or a subagent works, the typing tier's while you type. */
function skyRows(now: number): number {
  if (!settings.isOn || !settings.fireworks) return 0
  const showRows = show && now < show.end ? show.rows : 0
  return Math.max(showRows, live.isWorking || now < backgroundUntil ? 6 : 0, isSparkling(now) ? (TYPE_SKY_ROWS[typing.tier] ?? 6) : 0)
}

function skyDots(now: number, W: number, H: number, emit: Emit) {
  const current = show && now < show.end ? show : null
  const room = current ? wordClearing(current, now, W, H) : null
  if (current) showDots(current, now, W, H, emit, room)
  if (isSparkling(now)) {
    // Strong from the first key: while you are typing, the fountain never drops below its tier's height.
    const isActive = now - typing.lastAt < 1500
    typingFountain(now, W, H, typing.jets, Math.max(typingEnergy(now), isActive ? Math.min(1, 0.45 + 0.1 * typing.tier) : 0), around(room, emit), typing.tier)
  }
}

function blitSky($: Api, now: number) {
  if (!bandRequestId || bandCols === 0 || bandRows === 0 || isBlitBusy) return
  isBlitBusy = true
  $.ui
    .blit({ requestId: bandRequestId, key: 'fireworks', columns: bandCols, rows: bandRows, cells: paintDots(bandCols, bandRows, (emit) => skyDots(now, bandCols * 2, bandRows * 4, emit)) })
    .catch(() => {})
    .finally(() => {
      isBlitBusy = false
    })
}

// ---------------------------------------------------------------- every action answers back

/** Prompt length tiers: the TYPE meter climbs the same color ladder as HITs. */
const TYPE_TIERS = [0, 80, 200, 400, 800] as const
export function typeTier(len: number): number {
  let tier = 0
  TYPE_TIERS.forEach((at, i) => {
    if (len >= at) tier = i
  })
  return tier
}

/** Typing energy now: each edit kicks it, and it settles within a second or so. */
function typingEnergy(now: number): number {
  return typing.energy * Math.exp(-(now - typing.lastAt) / 600)
}

const METER = 8
// Braille dots filled bottom-up in a cell's left and right columns, for levels 0 to 4.
const COLUMN_FILL = [
  [0, 0x40, 0x44, 0x46, 0x47],
  [0, 0x80, 0xa0, 0xb0, 0xb8],
] as const

/** The TYPE meter: an equalizer of braille bars that dances while you type and settles flat when you stop. */
export function typeMeter(energy: number, now: number): string {
  let out = ''
  for (let i = 0; i < METER; i++) {
    let bits = 0
    for (let c = 0; c < 2; c++) {
      const k = i * 2 + c
      const wave = (Math.sin(now / 90 + k * 1.7) + Math.sin(now / 53 + k * 0.9)) / 4 + 0.5
      const level = energy < 0.05 ? 1 : Math.max(1, Math.min(4, Math.round(4 * energy * (0.35 + 0.65 * wave))))
      bits |= COLUMN_FILL[c]?.[level] ?? 0
    }
    out += String.fromCharCode(0x2800 | bits)
  }
  return out
}

/** A quick chip at the start of the HUD for something the person just did. */
function acknowledge($: Api, label: string, color: string, sound: string | null, ms = 1200) {
  if (!settings.isOn || !hasPerson()) return
  ack = { label, color, until: Date.now() + ms }
  if (sound) sfx($, sound, 0.6)
  ensureTicker($)
  $.ui.invalidate('ui.render')
}

/** An answer to a question or a permission prompt. Yes and no get the same show and sound: no nudge toward approving. */
function answered($: Api, label: string) {
  acknowledge($, label, LADDER[0] ?? '#e9e6f2', settings.fireworks ? null : 'decide', 900)
  startShow($, 'answer', { text: label === 'ANSWERED' ? 'OK' : label })
}

/** A word is in the sky, or on its way up. */
function isWordUp(now: number): boolean {
  return show !== null && now < show.end && show.shells.some((s) => s.kind === 'text' && now < s.at + RISE_MS + shellLife(s))
}

/**
 * What an edit did to the draft. A keystroke: a tick climbing the scale, the fountain leaping to a new spot and a
 * shell up from there in the next color of the rainbow. At 10, 25, 50, 100 and 200 HIT: the count in sparks. A
 * paste: its size in rainbow sparks.
 */
function onType($: Api, len: number, added: number) {
  const now = Date.now()
  if (len === 0) {
    typing = NO_TYPING
    $.ui.invalidate('ui.render')
    return
  }
  const was = typing.len === 0 ? NO_TYPING : typing
  const grew = Math.max(0, added)
  let { hits, pips, flashUntil, milestone, tier, jets } = was
  if (grew >= 40) {
    acknowledge($, `PASTE +${grew}`, LADDER[typeTier(len)] ?? '#e9e6f2', settings.fireworks ? null : 'paste', 1100)
    startShow($, 'paste', { text: `PASTE ${grew}` })
  } else if (grew > 0) {
    const isFirst = hits === 0
    hits += grew
    tier = typeHitTier(hits).level
    if (now - lastKeySoundAt > 70) {
      sfx($, `hit-${String(pips % 15).padStart(2, '0')}`, Math.min(0.4, 0.22 + tier * 0.03))
      lastKeySoundAt = now
    }
    if (isFirst) {
      startShow($, 'typeStart')
      typeSpin = random01()
    }
    // Every keystroke the fountain leaps somewhere new and a shell goes up from there, growing with the tier; out
    // to the sides while a word is up or this key sends one up.
    const mark = typeHitMilestone(hits)
    typeSpin = (typeSpin + 0.6180339887) % 1
    const x = typeSpot(typeSpin, mark > milestone || isWordUp(now))
    jets = [...jets.slice(-11), { at: now, x }]
    startShow($, KEY_SHOWS[tier] ?? 'key0', { palette: tier >= 5 ? 'rainbow' : KEY_COLORS[pips % KEY_COLORS.length], x })
    pips += 1
    if (mark > milestone) {
      startShow($, HIT_WORD_SHOWS[tier] ?? 'hitWord1', { text: `${mark}HIT`, holdMs: 650 })
      sfx($, 'combo', 0.6)
      milestone = mark
    }
    if (tier > was.tier) {
      sfx($, 'promote', 0.5)
      flashUntil = now + 450
    }
  }
  typing = { len, typed: was.typed + grew, hits, energy: Math.min(1, typingEnergy(now) + 0.14 + grew * 0.008), lastAt: now, pips, tier, flashUntil, milestone, jets }
  ensureTicker($)
}

/** Sent from the prompt box (or the bridge) by the person, not by a plugin or the SDK. */
function isFromBox(origin: { kind: string } | undefined): boolean {
  return origin?.kind === 'composer' || origin?.kind === 'bridge'
}

/** The draft left the box as a slash command: its HIT count and fountain end with it, with no GO!. */
function endDraft($: Api) {
  if (typing.len === 0) return
  typing = NO_TYPING
  $.ui.invalidate('ui.render')
}

/** Enter: GO! goes up in sparks, bigger for a longer prompt, and a context-rich prompt pays a little XP. */
async function launch($: Api, len: number) {
  typing = NO_TYPING
  if (!settings.isOn || !settings.typing || !hasPerson() || len === 0) return
  const xp = Math.min(15, Math.floor(len / 40))
  acknowledge($, xp > 0 ? `GO!  +${xp} XP` : 'GO!', LADDER[typeTier(len)] ?? '#e9e6f2', settings.fireworks ? null : 'launch', 1300)
  startShow($, len >= 400 ? 'go3' : len >= 80 ? 'go2' : 'go1')
  if (xp > 0) await award($, xp)
}

// Room for " 999 HIT ", the longest tier word and the TYPE meter.
const TYPING_WIDTH = 9 + 1 + 9 + 1 + METER

/**
 * What the person is doing right now: the HIT badge and TYPE meter while they write, in a slot that holds still
 * as the count climbs, and the chip for their last action, which comes and goes and so goes last in the row.
 */
function personPieces(T: BoxText, now: number): Person {
  const chip = ack && now < ack.until ? ` ${ack.label} ` : null
  let typed: Piece | null = null
  if (settings.typing && typing.len > 0) {
    const t = typeHitTier(typing.hits)
    const color = t.level >= 5 ? (RAINBOW[Math.floor(now / 120) % RAINBOW.length] ?? GOLD) : (LADDER[Math.min(4, t.level)] ?? '#e9e6f2')
    const badge = typing.hits > 0 ? ` ${typing.hits} HIT ` : ' TYPE '
    typed = slot(
      T,
      TYPING_WIDTH,
      0,
      T.Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          T.Text({ color, bold: true, inverse: typing.hits > 0 || now < typing.flashUntil, children: badge }),
          t.word ? T.Text({ color, bold: true, children: t.word }) : null,
          T.Text({ color, children: typeMeter(typingEnergy(now), now) }),
        ],
      }),
    )
  }
  return { typed, chip: chip && ack ? piece(chip.length, 0, T.Text({ color: ack.color, bold: true, inverse: true, children: chip })) : null }
}

// ---------------------------------------------------------------- commands

/** The results screen for this session, as plain lines (logged, and copied on request). */
export function recapLines(st: SessionStats, m: Meter | null, p: Profile, now: number): string[] {
  const played = st.startedAt > 0 ? elapsed(now - st.startedAt) : '0s'
  const lines = [
    `RESULTS  ${played} played   ${st.turns} turns   ${st.toolCalls} tool calls   Claude worked ${elapsed(st.workMs)}   best ${st.bestCombo} HIT   ${st.moments.commit} commits   ${st.moments.push} pushes`,
  ]
  const files = Object.entries(st.files).sort((a, b) => b[1] - a[1])
  if (files.length === 0) {
    lines.push('LOOT     no files edited yet')
  } else {
    const shown = files
      .slice(0, 8)
      .map(([f, n]) => (n > 1 ? `${f} ×${n}` : f))
      .join(', ')
    const more = files.length > 8 ? `, +${files.length - 8} more` : ''
    lines.push(`LOOT     ${files.length} file${files.length === 1 ? '' : 's'} edited: ${shown}${more}`)
  }
  const moves = Object.entries(st.tools)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
  if (moves.length > 0) lines.push(`MOVES    ${moves.map(([t, n]) => `${t} ×${n}`).join('   ')}`)
  const gold = m && m.usd !== null ? `   GOLD $${m.usd.toFixed(2)}` : ''
  lines.push(`TOKENS   in ${short(st.inputTokens)} (cache read ${short(st.cacheReadTokens)})   out ${short(st.outputTokens)}${gold}`)
  if (m) {
    const parts: string[] = []
    if (m.ctxPercent !== null) parts.push(`HP ${Math.max(0, 100 - m.ctxPercent)}% of context left`)
    for (const l of m.limits) {
      const refill = untilText(l.resetsAt, now)
      parts.push(`${limitName(l.kind)} limit ${l.percentUsed}% used${refill && refill !== 'now' ? `, refills in ${refill}` : ''}`)
    }
    if (parts.length > 0) lines.push(`STATUS   ${parts.join('   ')}`)
  }
  lines.push(`LEVEL    LV ${p.level} ${levelTitle(p.level)}   ${fmt(p.xp)}/${fmt(xpToNext(p.level))} XP`)
  return lines
}

