function onOff(arg: string, current: boolean): boolean {
  if (arg === 'on') return true
  if (arg === 'off') return false
  return !current
}

async function runCommand($: Api, args: string) {
  const [sub = '', arg = ''] = args.trim().toLowerCase().split(/\s+/)
  switch (sub) {
    case 'typing': {
      const isTyping = onOff(arg, settings.typing)
      await saveSettings($, { typing: isTyping })
      if (!isTyping) typing = NO_TYPING
      $.ui.toast(isTyping ? 'Typing reactions on: the TYPE meter, pips and GO!' : 'Typing reactions off')
      return
    }
    case 'fireworks': {
      if (arg === 'on' || arg === 'off') {
        await saveSettings($, { fireworks: arg === 'on' })
        if (arg === 'off') show = null
        $.ui.toast(arg === 'on' ? 'Fireworks on' : 'Fireworks off: the HUD stays, the sky closes')
        $.ui.invalidate('ui.render')
        return
      }
      if (!settings.isOn) {
        $.ui.toast('DOPA MODE is paused. /dopa on brings it back')
        return
      }
      if (!settings.fireworks) {
        $.ui.toast('Fireworks are off. /dopa fireworks on brings them back')
        return
      }
      startShow($, 'preview')
      return
    }
    case 'stats': {
      const p = await read($, profileAtom)
      const m = p.moments
      $.ui.log(`LV ${p.level} ${levelTitle(p.level)}   ${fmt(p.xp)}/${fmt(xpToNext(p.level))} XP   total ${fmt(p.totalXp)} XP`)
      $.ui.log(`Clears ${fmt(p.clears)}   commits ${m.commit}   pushes ${m.push}   pull requests ${m.pr}   merged ${m.merge}`)
      $.ui.log(`Best ${p.bestCombo} HIT   best streak ${p.bestStreak}   current streak ${p.streak}`)
      $.ui.log(`Sound ${settings.sfx ? 'on' : 'off'}   spinner ${settings.spinner ? 'on' : 'off'}`)
      return
    }
    case 'sfx':
    case 'sound':
    case 'mute':
    case 'unmute': {
      const sfxOn = sub === 'mute' ? false : sub === 'unmute' ? true : onOff(arg, settings.sfx)
      await saveSettings($, { sfx: sfxOn })
      $.ui.toast(sfxOn ? 'Sound effects on' : 'Sound effects off')
      if (sfxOn) sfx($, 'coin')
      return
    }
    case 'spinner': {
      const spinner = onOff(arg, settings.spinner)
      await saveSettings($, { spinner })
      $.ui.toast(spinner ? 'Rainbow spinner on' : 'Stock spinner back')
      return
    }
    case 'on':
    case 'off': {
      await saveSettings($, { isOn: sub === 'on' })
      $.ui.toast(sub === 'on' ? 'DOPA MODE on' : 'DOPA MODE paused')
      return
    }
    case 'recap': {
      const [stats, meter, p] = await Promise.all([read($, statsAtom), read($, meterAtom), read($, profileAtom)])
      const lines = recapLines(stats, meter, p, Date.now())
      lines.forEach((line) => $.ui.log(line))
      if (arg === 'copy') {
        const copied = await $.ui.copy({ text: lines.join('\n') })
        $.ui.toast(copied.isCopied ? 'Recap copied to the clipboard' : `Copy failed: ${copied.reason}`)
      }
      return
    }
    case 'daily':
      await drawDaily($)
      return
    case 'dex':
      await showDex($)
      return
    case 'trophies':
      await showTrophies($)
      return
    case 'focus':
      if (arg === 'stop') await stopFocus($)
      else await startFocus($, 'focus', clampMinutes(arg, 25))
      return
    case 'break':
      if (arg === 'stop') await stopFocus($)
      else await startFocus($, 'break', clampMinutes(arg, 5))
      return
    case 'boss':
      await checkBoss($)
      return
    case 'legend': {
      LEGEND.forEach((line) => $.ui.log(line))
      return
    }
    case 'meters': {
      const meters = onOff(arg, settings.meters)
      await saveSettings($, { meters })
      $.ui.toast(meters ? 'Meters on' : 'Meters off')
      return
    }
    case 'alerts': {
      const alerts = onOff(arg, settings.alerts)
      await saveSettings($, { alerts })
      $.ui.toast(alerts ? 'Alerts on' : 'Alerts off')
      return
    }
    case 'reset': {
      if (arg !== 'confirm') {
        $.ui.log('This wipes your level, XP, streak, counts and trophies. Run /dopa reset confirm to do it.')
        return
      }
      await $.store.set('profile', FRESH_PROFILE)
      // Starting over earns every trophy again, with its show.
      await $.store.set('trophies', [])
      await update($, profileAtom, () => FRESH_PROFILE)
      $.ui.toast('Fresh account. LV 1 again')
      return
    }
    default:
      HELP.forEach((line) => $.ui.log(line))
  }
}

// ---------------------------------------------------------------- hooks

export const register: Register = (on) => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    isInteractive = e.isInteractive || e.surface !== null
    try {
      if ((await $.session.surfaces()).length > 0) isInteractive = true
    } catch {
      // Keep what session.start said.
    }
    cwd = e.cwd
    await loadFromStore($)
    if ((await read($, statsAtom)).startedAt === 0) await update($, statsAtom, (st) => ({ ...st, startedAt: Date.now() }))
    try {
      const meter = toMeter(await $.session.usage())
      await setMeter($, meter)
      if (meter.ctxPercent !== null) ctxAlerts($, meter.ctxPercent)
      limitAlerts($, meter.limits)
    } catch {
      // No reading before the first response.
    }
    // After a hot reload, pick up where the old copy of this module left off.
    live = await read($, turnAtom)
    if (live.isWorking) ensureTicker($)
    const focus = await read($, focusAtom)
    if (focus) {
      if (focus.endsAt <= Date.now()) void finishFocus($).catch(() => {})
      else armFocus($, focus)
    }
    try {
      await $.command.register({
        name: 'dopa',
        description: 'DOPA MODE (DOPA as in dopamine): fireworks, recap, daily card, trophies, focus timer',
        argumentHint: '[fireworks|typing|recap|daily|dex|trophies|focus|break|boss|stats|sfx|alerts|meters|legend|spinner|on|off|help]',
        immediate: true,
      })
    } catch {
      // Name taken: the HUD, combos and fireworks still work.
    }
    return result
  })

  // /clear, /resume and /branch put every $.state value back to its default.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    const result = await next(e)
    await loadFromStore($)
    await update($, statsAtom, (st) => (st.startedAt === 0 ? { ...st, startedAt: Date.now() } : st))
    return result
  })

  on('command.run', { command: 'dopa' }, async ($, e) => {
    if (isFromBox(e.origin)) endDraft($)
    await runCommand($, e.args)
    return {}
  })

  // Captures a command the first time you run it. Observes only: the command runs as it would.
  on('command.run', async ($, e, next) => {
    // Typed at the prompt: the box has been sent, whether or not prompt.submit saw it.
    if (isFromBox(e.origin)) endDraft($)
    const result = await next(e)
    if (e.command !== 'dopa' && settings.isOn && hasPerson()) {
      const isNew = await capture($, e.command).catch(() => false)
      if (!isNew) {
        acknowledge($, `/${e.command}`, LADDER[1] ?? '#3d8bff', 'coin', 900)
        startShow($, 'command')
      }
    }
    return result
  })

  // Compacting by hand before auto-compact earns Self care.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    const isSkipped = 'skip' in result && Boolean(result.skip)
    if (!isSkipped && e.trigger === 'manual' && lastCtx !== null && lastCtx >= 70) await achieve($, 'self-compact').catch(() => {})
    return result
  })

  // Typing: the edit lands exactly as typed. Only the draft's length is used; the text is never kept.
  on('prompt.edit', async ($, e, next) => {
    const out = await next(e)
    try {
      if (settings.isOn && settings.typing && hasPerson()) {
        const box = out as { text?: unknown }
        const len = typeof box.text === 'string' ? box.text.length : e.text.length - (e.end - e.start) + e.inputText.length
        onType($, len, e.inputText.length - (e.end - e.start))
      }
    } catch {}
    return out
  })

  // Enter: the prompt goes exactly as typed. Only its length is used.
  on('prompt.submit', async ($, e, next) => {
    const out = await next(e)
    try {
      const isDropped = 'drop' in out && Boolean((out as { drop?: unknown }).drop)
      const isPerson = e.origin.kind === 'composer' || e.origin.kind === 'bridge'
      if (!isDropped && isPerson) {
        if (e.text.startsWith('/')) endDraft($)
        else void launch($, e.text.length).catch(() => {})
      }
    } catch {}
    return out
  })

  // A /config pick: the setting changes exactly as chosen.
  on('config.set', async ($, e, next) => {
    const out = await next(e)
    try {
      const isDenied = 'deny' in out && Boolean((out as { deny?: unknown }).deny)
      if (!isDenied && e.origin.kind !== 'plugin') {
        acknowledge($, `SET  ${e.key}`, LADDER[1] ?? '#3d8bff', settings.fireworks ? null : 'decide', 1000)
        startShow($, 'set')
      }
    } catch {}
    return out
  })

  on('turn.start', async ($, e, next) => {
    turnFiles = new Set()
    live = { isWorking: true, combo: 0, startedAt: Date.now(), word: '', move: '' }
    await update($, turnAtom, () => live)
    if (settings.isOn && hasPerson()) ensureTicker($)
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    if (live.isWorking) {
      const combo = live.combo + 1
      live = { ...live, combo, move: moveLabel(e) }
      lastHitAt = Date.now()
      await update($, turnAtom, () => live)
      if (settings.isOn && hasPerson()) {
        const tier = COMBO_TIERS.find((t) => t.at === combo && t.word)
        if (tier) {
          $.ui.toast(`${combo} HIT  ${tier.word}`, { timeoutMs: 2500 })
          sfx($, 'combo', 0.7)
        } else {
          // Each hit climbs a pentatonic scale, so a long run of tool calls sounds like it is building.
          sfx($, `hit-${String(Math.min(combo - 1, 14)).padStart(2, '0')}`, 0.35)
        }
        if (combo === 10 || combo === 30 || combo === 50) void achieve($, `hit-${combo}` as TrophyId).catch(() => {})
        startShow($, combo >= 50 ? 'hit5' : combo >= 30 ? 'hit4' : combo >= 20 ? 'hit3' : combo >= 10 ? 'hit2' : combo >= 5 ? 'hit1' : 'hit0')
        if (combo === 5 || combo === 10 || combo === 20 || combo === 30) startShow($, combo >= 30 ? 'hitWord3' : combo >= 20 ? 'hitWord2' : 'hitWord1', { text: `${combo}HIT` })
        if (combo === 50) startShow($, 'rainbow')
      }
    } else if (e.agentId && settings.isOn && hasPerson()) {
      // The turn is over but a subagent works on: each call it makes lights the wait, without counting as a HIT.
      backgroundUntil = Date.now() + BACKGROUND_SKY_MS
      startShow($, 'background')
    }
    if (e.tool === 'AskUserQuestion') yourMove($, 'question', 'Claude has a question for you')
    const result = await next(e)
    const file = editedFile(e, cwd)
    const isDone = !('deny' in result && result.deny) && !('isError' in result && result.isError)
    if (file && isDone && live.isWorking) turnFiles.add(file)
    await update($, statsAtom, (st) => ({
      ...st,
      toolCalls: st.toolCalls + 1,
      tools: { ...st.tools, [e.tool]: (st.tools[e.tool] ?? 0) + 1 },
      files: file && isDone ? { ...st.files, [file]: (st.files[file] ?? 0) + 1 } : st.files,
    }))
    // The person's answer first, so what the call then earned (PASS, COMMIT, PUSH) goes up after it.
    if (asking.length > 0 && takeAnswered(e as Record<string, unknown>)) {
      // The permission prompt was answered: the call ran, or it was turned down.
      let text = ''
      try {
        text = JSON.stringify(result).slice(0, 4000)
      } catch {}
      const isNo = ('deny' in result && Boolean(result.deny)) || /doesn't want to proceed|was rejected|user rejected|denied/i.test(text)
      answered($, isNo ? 'NO' : 'YES')
    }
    if (SHELL_TOOLS.has(e.tool) && settings.isOn) {
      const command = String((e as { command?: unknown }).command ?? '')
      await readBash($, command, result)
      await onMoments($, command, result)
      await onErrorCount($, command, result)
    }
    if (e.tool === 'AskUserQuestion' && isDone) answered($, 'ANSWERED')
    if (e.tool === 'TodoWrite' && isDone && settings.isOn) onTodoWrite($, e)
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    const usage = e.usage
    const tokensIn = usage ? usage.input_tokens + usage.cache_creation_input_tokens + usage.cache_read_input_tokens : 0
    const tokensOut = usage?.output_tokens ?? 0
    await update($, statsAtom, (st) => ({
      ...st,
      inputTokens: st.inputTokens + tokensIn,
      cacheReadTokens: st.cacheReadTokens + (usage?.cache_read_input_tokens ?? 0),
      outputTokens: st.outputTokens + tokensOut,
    }))
    if (e.agentId) return result // a subagent's turn: its tokens count, but it does not clear
    const turn = live
    live = { ...turn, isWorking: false }
    await update($, turnAtom, () => live)
    await update($, statsAtom, (st) => ({
      ...st,
      turns: st.turns + 1,
      workMs: st.workMs + e.durationMs,
      bestCombo: Math.max(st.bestCombo, turn.combo),
    }))
    if (!settings.isOn || !hasPerson()) return result
    if (e.isAborted) {
      await loseStreak($)
      return result
    }
    if (e.reason !== 'answer') return result
    await clear($, turn.combo, e.durationMs, turnFiles.size)
    if (alertsOn() && e.durationMs >= 60_000) {
      $.ui.toast(`STAGE CLEAR  ${elapsed(e.durationMs)}  ${turn.combo} HIT`, { timeoutMs: 6000 })
    }
    return result
  })

  // After each turn, and when a plan limit moves: refresh the meters, warn at thresholds.
  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    const meter = toMeter(e)
    await setMeter($, meter)
    if (e.changed.includes('context') && meter.ctxPercent !== null) ctxAlerts($, meter.ctxPercent)
    if (e.changed.includes('rateLimits')) limitAlerts($, meter.limits)
    return result
  })

  // Claude is waiting on you: a permission prompt, or a long wait at the prompt.
  // Claude's task list: count tasks created and done; each one done goes up as done/total.
  on('classic.TaskCreated', async ($, e, next) => {
    const result = await next(e)
    if (tasks.created.size > 0 && tasks.done.size >= tasks.created.size) tasks = { created: new Set(), done: new Set() }
    tasks.created.add(e.task_id)
    return result
  })
  on('classic.TaskCompleted', async ($, e, next) => {
    const result = await next(e)
    tasks.created.add(e.task_id) // created before the mod loaded
    if (!tasks.done.has(e.task_id)) {
      tasks.done.add(e.task_id)
      onTaskDone($, tasks.done.size, tasks.created.size)
    }
    return result
  })

  // A subagent finished its work: a small shell.
  on('classic.SubagentStop', async ($, e, next) => {
    const result = await next(e)
    if (settings.isOn && hasPerson()) startShow($, 'agent')
    return result
  })

  // A permission dialog opens. Watched only: the hook passes on what it got and decides nothing, so the person's
  // answer is theirs. The notification for it comes only after a wait, too late for a quick YES.
  on('classic.PermissionRequest', async ($, e, next) => {
    const result = await next(e)
    asking = [...asking.slice(-7), { tool: e.tool_name, input: e.tool_input }]
    return result
  })

  on('classic.Notification', async ($, e, next) => {
    const result = await next(e)
    yourMove($, e.notification_type, e.message)
    return result
  })

  // The desktop app (or a phone) can attach after the session started.
  on('session.attach', async ($, e, next) => {
    clients.add(e.clientId)
    return next(e)
  })

  on('session.detach', async ($, e, next) => {
    clients.delete(e.clientId)
    return next(e)
  })

  // The band above the prompt: the sky, the idle HUD or FEVER while Claude works, and the meters.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const s = await read($, settingsAtom)
    if (!s.isOn || e.props.hasSurvey) return next(e)
    const [p, turn, meter, stats] = await Promise.all([read($, profileAtom), read($, turnAtom), read($, meterAtom), read($, statsAtom)])
    const [tests, boss, focus] = await Promise.all([read($, testsAtom), read($, bossAtom), read($, focusAtom)])
    const T = $.ui.resolve(e)
    const columns = Math.max(20, e.props.bodyColumns - 2)
    const phase = Math.floor(performance.now() / 120)
    const now = Date.now()
    const person = personPieces(T, now)
    const row = turn.isWorking ? feverRow(T, turn, p, columns, phase, now, person) : idleRow(T, p, columns, person)
    const rows: RenderElement[] = [row]
    if (s.meters) {
      const isLowHp = meter !== null && meter.ctxPercent !== null && meter.ctxPercent >= 85
      const compact =
        isLowHp && !turn.isWorking && 'Button' in T
          ? T.Button({ key: 'compact', label: 'Compact now', onPress: () => compactNow($) })
          : null
      const more = [focusPiece(T, focus, now), testsPiece(T, tests, now), bossPiece(T, boss, now)].filter((x): x is Piece => x !== null)
      const status = statusRow(T, meter, stats, columns, compact, more)
      if (status) rows.push(status)
    }
    let strip: RenderElement | null = null
    const want = skyRows(now)
    if (want >= 3) {
      const cols = Math.max(18, Math.min(158, columns - 2)) // inside the frame
      // The sky opens as tall as the moment wants, in what the HUD rows and the frame leave. A subagent list or the
      // command menu under the prompt can leave the band only a few rows; rather than shrink the words to a dot a
      // pixel, the sky takes the frame's two rows, then the meters row.
      let room = e.props.maxRows - rows.length - 2
      const isFramed = room >= WORD_ROWS || want < WORD_ROWS
      if (!isFramed) room += 2
      if (room < WORD_ROWS && want >= WORD_ROWS && rows.length > 1) {
        rows.pop()
        room += 1
      }
      const skyH = Math.min(want, room)
      // Raster exists in every table but draws only in the terminal, so pick by surface.
      if (skyH >= 3 && e.surface === 'terminal' && 'Raster' in T) {
        bandRequestId = e.requestId
        bandCols = cols
        bandRows = skyH
        const sky = T.Raster({ key: 'fireworks', columns: cols, rows: skyH, cells: paintDots(cols, skyH, (emit) => skyDots(now, cols * 2, skyH * 4, emit)) })
        // A dim frame marks where the fireworks go; nothing is drawn behind them.
        strip = isFramed ? T.Box({ key: 'sky', borderStyle: 'round', borderDimColor: true, children: [sky] }) : T.Box({ key: 'sky', paddingX: 1, children: [sky] })
      } else if (skyH >= 3 && e.surface === 'desktop' && 'Svg' in T) {
        strip = T.Svg({ source: svgDots(720, skyH, (emit) => skyDots(now, 200, skyH * 4, emit)), alt: 'Fireworks', height: Math.round(skyH * 4 * 3.6) })
      }
    }
    const theirs = await next(e)
    return T.Box({ flexDirection: 'column', paddingX: 1, children: [strip, ...rows, theirs] })
  })

  // The working line: what Claude is touching, the hit count, and the time.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const [s, turn] = await Promise.all([read($, settingsAtom), read($, turnAtom)])
    if (!s.isOn || !s.spinner || !turn.isWorking) return next(e)
    if (e.surface !== 'terminal') {
      if (turn.combo === 0) return next(e)
      return next({ ...e, props: { ...e.props, suffix: `${e.props.suffix}  ${turn.combo} HIT` } })
    }
    const T = $.ui.resolve(e)
    const phase = Math.floor(performance.now() / 110)
    const tier = comboTier(turn.combo)
    const isTool = e.props.mode === 'tool-use' || e.props.mode === 'tool-input'
    const doing = isTool && turn.move ? turn.move : e.props.mode === 'responding' ? 'writing' : 'thinking'
    const children: RenderElement[] = [0, 1, 2].map((i) =>
      T.Text({ color: ladderColor(tier.level, phase + i), bold: true, dimColor: (phase + 2 - i) % 3 !== 0, children: '▸' }),
    )
    children.push(T.Text({ children: `  ${doing}` }))
    if (turn.combo > 0) children.push(T.Text({ children: '   ' }), lamp(T, `${turn.combo} HIT`, tier.level, phase))
    children.push(T.Text({ dimColor: true, children: `   ${elapsed(Date.now() - turn.startedAt)}` }))
    return T.Box({ flexDirection: 'row', children })
  })
}

