// The state contract for DOPA MODE (DOPA is short for dopamine). Claude Code reads it to check every
// $.state value the hooks module reads or writes.

/** Milestones Claude reached for you. */
export type Moment = 'commit' | 'push' | 'pr' | 'merge'

export type Profile = {
  level: number
  /** XP inside the current level. */
  xp: number
  totalXp: number
  /** Turns finished. */
  clears: number
  /** Turns finished in a row without an interrupt. */
  streak: number
  bestStreak: number
  bestCombo: number
  moments: Record<Moment, number>
}

export type Settings = {
  isOn: boolean
  sfx: boolean
  spinner: boolean
  /** The HP / STAMINA / GOLD / LOOT row under the HUD. */
  meters: boolean
  /** Threshold warnings, YOUR MOVE and QUEST CLEAR. */
  alerts: boolean
  typing: boolean
  fireworks: boolean
}

/** One plan limit window, as $.session.usage() reports it. */
export type Limit = { kind: string; percentUsed: number; resetsAt?: string }

/** The latest usage reading: context fill, plan limits and cost. */
export type Meter = {
  ctxPercent: number | null
  ctxTokens: number | null
  ctxWindow: number
  limits: Limit[]
  usd: number | null
}

/** What this session has done, for the band and /dopa recap. */
export type SessionStats = {
  /** Date.now() when the session (or the last /clear) started. */
  startedAt: number
  turns: number
  toolCalls: number
  tools: Record<string, number>
  /** Edited files, relative to the session's directory, with edit counts. */
  files: Record<string, number>
  inputTokens: number
  cacheReadTokens: number
  outputTokens: number
  workMs: number
  bestCombo: number
  moments: Record<Moment, number>
}

export type TurnInfo = {
  isWorking: boolean
  combo: number
  /** Date.now() when the turn started. */
  startedAt: number
  word: string
  move: string
}

/** The last test run Claude made, read from its output. */
export type TestRun = { passed: number; failed: number; isKnown: boolean; isGreen: boolean; at: number }
export type TestState = { last: TestRun | null; greenStreak: number; wasRed: boolean }

/** Pull request checks, read from gh output. */
export type BossState = { total: number; passed: number; failed: number; pending: number; at: number; isDefeated: boolean }

export type FocusState = { kind: 'focus' | 'break'; minutes: number; endsAt: number } | null

declare module 'claude-code' {
  interface PluginState {
    'dopa-mode': {
      profile: Profile
      settings: Settings
      turn: TurnInfo
      meter: Meter | null
      stats: SessionStats
      tests: TestState
      boss: BossState | null
      focus: FocusState
    }
  }
}
